/* 终章 · 汉室余晖 — 1:1 演出流，逆向自 R_58.eex */
(function(){
 if(!window.JW_CHAPTERS) window.JW_CHAPTERS=[];
 window.JW_CHAPTERS.push({"id":"ch58","num":58,"title":"终章 · 汉室余晖","desc":"终章 · 汉室余晖（原版剧本 R_58.eex 完整演出流）","intro":{"title":"终章 · 汉室余晖","script":[{"op":"clear_flags","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[117]},{"op":"change_scene","args":[2,65535,65535,16,65535]},{"op":"actor_appear","args":[0,51,68,0,0]},{"op":"actor_appear","args":[258,43,61,0,10]},{"op":"actor_appear","args":[259,46,57,1,10]},{"op":"actor_appear","args":[260,54,58,2,10]},{"op":"actor_appear","args":[261,59,55,1,10]},{"op":"actor_appear","args":[262,50,50,0,10]},{"op":"actor_appear","args":[263,42,48,3,10]},{"op":"actor_appear","args":[148,48,28,2,0]},{"op":"actor_appear","args":[147,54,28,2,0]},{"op":"actor_appear","args":[264,45,23,2,0]},{"op":"actor_appear","args":[265,50,23,2,0]},{"op":"actor_appear","args":[266,55,23,2,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["孤臣之死"]},{"op":"place_name","args":["成都 宫殿"]},{"op":"dialog","args":["&步兵3\n这家伙是人吗？一个人就杀了我们这么多\n弟兄…\n&胡渊\n不用害怕，这家伙已经是强弩之末了。\n&胡烈\n鹞鸱，没有我的命令，不准往前一步！"]},{"op":"actor_face","args":[148,0,1]},{"op":"dialog","args":["&胡渊\n这家伙害死我们这么多弟兄，又差点\n害死您，为什么还要阻止我杀他？"]},{"op":"actor_action","args":[147,6]},{"op":"dialog","args":["&胡烈\n姜伯约将军，在下安定胡烈，方才小儿有\n冒犯之处，敬请原谅。\n&胡烈\n现在贼首钟会已死，您已经没有继续奋战\n的必要，何不就此投降？我会向朝廷说是\n您协助平乱的。\n&胡渊\n爹，这岂不是欺君？\n&姜维\n看来你还是完全不了解我呀…我从来没有\n为钟会效忠的意思，他不管是死或活都没\n有任何差别。\n&胡烈\n那您就更不需要再战斗了，放下刀剑，我\n很期待我们将来的共事。\n&姜维\n当钟会死的时候，复兴大汉的计画就已经\n确定破灭，我也无法继续活下去了。\n&胡烈\n这又是何苦呢？您过去也是我们大魏的\n臣子，现在只是回归而已，不算是叛臣。\n&姜维\n要知道，如果让我继续活下去，我会不断\n想要找机会复国，不停再度背叛你们，\n这样的人对你们只是威胁而已。\n&胡烈\n为什么要这么固执？明明当时您不也\n投降了诸葛亮？\n&姜维\n情况完全不同，当时我没有受大魏的策名\n，而我效忠的太守直接抛弃了我。\n&姜维\n丞相拯救了我并予机会，让我能获得\n今天的地位。\n&姜维\n这个知遇之恩，就算用十生都难以回报。\n&姜维\n然而我却让大汉在我眼前灭亡，就算拚尽\n最后的努力也无力回天。现在只有以一死\n来表示对丞相的歉意。\n&胡渊\n爹！快让我亲手宰了他！\n&胡烈\n住手！难道你连一点武人的精神都没有？\n&胡烈\n我明白了，安定胡烈在此守护您走上最后\n一程，希望您一路好走。"]},{"op":"actor_face","args":[148,0,2]},{"op":"delay","args":[10]},{"op":"actor_action","args":[0,11]},{"op":"dialog","args":["&姜维\n丞相，姜维实在是没有脸见您，北伐不但\n无功，还让大汉落入贼人之手。"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[6,46,44,2,0]},{"op":"actor_appear","args":[19,52,44,2,0]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&傅佥\n大将军，我们每个人都以您为荣。\n&赵广\n待在您帐下是我们一生中最荣耀的事。\n&姜维\n为什么？为什么我会看到已死之人？"]},{"op":"delay","args":[5]},{"op":"actor_select","args":[0,6,0,0,0,0,6]},{"op":"actor_select","args":[0,19,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[51,40,44,2,0]},{"op":"actor_appear","args":[25,46,44,2,0]},{"op":"actor_appear","args":[26,52,44,2,0]},{"op":"actor_appear","args":[155,58,44,2,0]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&赵云\n已经够了，就算现在到这边，面对先帝\n也可以抬头挺胸。\n&魏延\n在绝望时刻永不放弃，你比我这个一怒\n之下就舍弃一切的匹夫要强太多了。\n&尹赏\n伯约，太了不起了，你真的是我们冀城\n的骄傲。\n&陈祗\n没想到最后还是这样的结局，你叫我\n怎么说你？\n&姜维\n赵将军？文长？尹兄？奉宗？"]},{"op":"delay","args":[5]},{"op":"actor_select","args":[0,25,0,0,0,0,6]},{"op":"actor_select","args":[0,26,0,0,0,0,6]},{"op":"actor_select","args":[0,155,0,0,0,0,6]},{"op":"actor_select","args":[0,51,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[61,51,44,2,0]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&诸葛亮\n伯约，不需要道歉，亮还没有你这样的\n勇气，宁愿让自己背负恶名，也要赌上\n最后的一点机会来复国。\n&姜维\n但是我还是失败了…\n&诸葛亮\n成败不足以论英雄，我们只是尽自己所能\n去做而已。\n&姜维\n如果大家责怪我的话，或许我还会好受\n一点…\n&诸葛亮\n亮真的没有办法责备一个已经尽力的人。\n就像先帝也没有责怪亮一样。\n&诸葛亮\n放心吧，大汉就算现在灭亡，但是继承\n大汉精神的人还是在，大汉的立国根基\n可不是这么容易被消灭的。"]},{"op":"delay","args":[5]},{"op":"actor_select","args":[0,61,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[802,51,44,2,0]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n香…果然最后的最后，是你来迎接我…\n&尹香\n你已经尽力了，不要再责怪自己。\n&尹香\n当初我对你的三个请求，其实只是要你\n坚强地活下去而已。\n&尹香\n什么功成名就，其实我一点也不在乎。\n&尹香\n你所做的远超过我的请求，这四十年你\n也名满三国，以一己之力撑起蜀国。\n&尹香\n所以真的够了，不需要再让自己这么\n辛苦了。\n&姜维\n真的可以休息了吗？\n&尹香\n走吧…卸下一切的重担…到这里来和大家\n一起相聚吧。"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n各位，请原谅我先走一步，希望大家能\n平安无事…"]},{"op":"actor_select","args":[0,802,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"actor_face","args":[0,13,0]},{"op":"delay","args":[5]},{"op":"play_music","args":[35,1]},{"op":"delay","args":[5]},{"op":"actor_face","args":[0,10,2]},{"op":"play_music","args":[38,1]},{"op":"delay","args":[10]},{"op":"dialog","args":["&胡渊\n该死！我生不能杀其人，死也要戮其尸！"]},{"op":"actor_move","args":[0,148,0,51,63,2]},{"op":"actor_action","args":[148,13]},{"op":"dialog","args":["&胡烈\n鹞鸱，住手！"]},{"op":"actor_action","args":[148,0]},{"op":"actor_face","args":[148,0,0]},{"op":"dialog","args":["&胡渊\n爹！"]},{"op":"dialog","args":["&胡烈\n他也是一世豪杰，好好安葬吧。"]},{"op":"delay","args":[10]},{"op":"dialog","args":["公元二六四年正月十八日，姜维苦心策画\n的复国大计宣告失败，他本人被蜂拥而上\n的乱军所害，年六十三岁。\n\n据《三国志　姜维传》的注引《世语》\n记载，姜维死后腹部被剖开，发现他的\n胆跟斗一样大。\n\n姜维死后，后世对他的评价两极化，有\n认为他忠勇忘身，虽败不失为名将。也有\n认为他穷兵黩武，导致蜀汉灭亡。\n\n曾经和姜维共事过的郤正的看法可供参考\n：“凡人之谈，常誉成毁败，扶高抑下，\n咸以姜维投厝无所，身死宗灭，以是贬削\n\n，不复料擿，异乎春秋褒贬之义矣。”"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"delay","args":[5]},{"op":"change_scene","args":[2,65535,65535,26,65535]},{"op":"actor_appear","args":[9,46,54,1,1]},{"op":"actor_appear","args":[258,51,48,0,10]},{"op":"actor_appear","args":[259,53,53,3,10]},{"op":"actor_appear","args":[260,50,60,2,10]},{"op":"actor_appear","args":[261,55,59,1,10]},{"op":"actor_appear","args":[262,59,64,1,10]},{"op":"actor_appear","args":[263,57,52,2,10]},{"op":"actor_appear","args":[145,80,60,3,0]},{"op":"actor_appear","args":[264,74,54,3,0]},{"op":"actor_appear","args":[265,74,64,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["最后的袁氏"]},{"op":"place_name","args":["成都 宫门"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&王买\n这家伙应该可以靠近了吧，已经好一阵子\n一动也不动。\n&步兵7\n将军要靠近请自己靠近。\n&王买\n夏侯咸那些家伙，把最难打又没什么价值\n留给我们，自己跑去打钟会。\n&步兵8\n您明明知道，还一直让弟兄们去送死。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&袁綝\n看来我真的没力了，这些人要是再涌上来\n，也就只有乖乖等死。\n&袁綝\n死前就来看这封信吧…"]},{"op":"delay","args":[5]},{"op":"dialog","args":["袁綝吾儿：\n在袁家最困顿的时候让你降生，为父感到\n非常抱歉。本来想要教训那背叛者曹瞒，\n\n却没想曹瞒用尽诡诈手法，骗得许攸、\n张郃等人背叛，使为父不幸在官渡惨败。\n数万大军尽数葬送。\n\n接著又在仓亭败给那狡猾曹瞒，一时间竟\n使那竖子成名。现虽为父坐镇河北，曹瞒\n不敢北上，但冀州各郡县纷起叛乱，\n\n为父光稳定河北就已心力交瘁，近日更\n感到力不从心，深知已不久于人世。你\n却在此时降生，让为父感到悲怆莫名。\n\n为父深知显思（袁谭）和显甫（袁尚）\n两人水火不容，家臣又分成两派相互\n攻讦。\n\n只怕日后两人相争，你会被正室刘夫人\n或其他兄弟所害，所以将你送到汝南袁家\n本家避祸。\n\n若日后河北纷乱，你在汝南还可以避开\n这灾祸，免于骨肉相残之争。就算曹瞒\n侥幸入侵河北，你也不至受害。\n\n我相信曹瞒这家伙不管再无耻，应该也\n不至于敢把屠刀对向汝南的袁家本家，\n这是连董卓都不敢为之恶行。\n\n日后长大，你可以不用挂念这未谋面的\n父亲，但请你要记得，要时时以四世三公\n的袁家为荣，你流的血是最宝贵的。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&袁綝\n我终于明白义父为什么不杀我，还坚持\n让我姓袁的道理。\n&袁綝\n一个惨杀义父挚友的冷血动物，却在这时\n表现出人性来，真叫人不知道怎么反应。\n&袁綝\n也罢，到那里再好好揍你一顿吧。"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[266,42,54,1,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"dialog","args":["&步兵9\n贼首钟会和姜维都已经伏法，我军已经\n平乱成功。\n&袁綝\n是吗？伯约也死了？\n&王买\n那还等什么，把眼前这家伙也一起干掉\n，为那些死难的弟兄们报仇。\n&步兵9\n是！"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[266,13]},{"op":"play_music","args":[34,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[2,65535,65535,41,65535]},{"op":"actor_appear","args":[140,41,65,1,0]},{"op":"actor_appear","args":[57,55,65,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["庞会的复仇"]},{"op":"place_name","args":["成都 关家"]},{"op":"dialog","args":["&庞会\n整个关家就只剩下你一个人了，\n不害怕吗？\n&关彝\n我又有什么好怕的？只恨我没有能力守护\n家人，让他们命丧你这奸贼之手。\n&庞会\n奸贼？！关羽斩杀我父亲，我为父报仇\n乃是天经地义。\n&关彝\n战场上交锋造成的死伤，也想要算到我\n祖父身上来？\n&庞会\n哼，那又如何？我生存的目的就是复仇，\n为了复仇，我不惜对司马家，甚至钟会\n卑躬屈膝，就是在等今天的机会。\n&关彝\n哈哈哈，我明白了。你只不过是个悲哀的\n胆小鬼而已。\n&关彝\n父亲被称为忠臣，你无力去对抗篡国之\n贼，只好用报父仇这种藉口掩饰自己的\n无能。\n&庞会\n住口！\n&关彝\n可悲呀，当年庞德大喊：“我宁做国家\n的鬼，也不做贼将。”自己的儿子却当了\n贼将…\n&庞会\n你们通通给我去死吧！\n&关彝\n（三叔，至少关家还有你逃过一劫，关家\n以后的传承就交给你了…）"]},{"op":"fade_in","args":[]},{"op":"delay","args":[3]},{"op":"change_scene","args":[2,65535,65535,41,65535]},{"op":"actor_appear","args":[17,59,38,2,0]},{"op":"actor_appear","args":[213,55,48,1,0]},{"op":"actor_appear","args":[49,59,48,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["刘禅的悔恨"]},{"op":"place_name","args":["成都 刘禅住处"]},{"op":"dialog","args":["&刘禅\n右车骑将军，外面的情况到底怎么样？"]},{"op":"actor_action","args":[17,6]},{"op":"dialog","args":["&廖化\n宫殿那边情况不明，但是外面的乱军\n到处烧杀掳掠，太仆蒋显和太子都已经\n罹难了。\n&刘禅\n什么？！太子遇害了？\n&廖化\n所以请陛下千万不可以踏出门一步。\n&刘禅\n看见自己的儿子被杀，却只能在这里当\n缩头乌龟，朕还真是窝囊。\n&张皇后\n就算已经亡国，您也还是一国之君，\n要学会保护自己。\n&张皇后\n现在出去逞匹夫之勇又有什么用？"]},{"op":"actor_action","args":[17,0]},{"op":"actor_face","args":[213,0,0]},{"op":"dialog","args":["&张皇后\n右车骑将军，这里就交给我，要挡住这些\n乱军一时半刻还没有问题。\n&张皇后\n我希望你现在去找贼军的主将，不管是\n卫瓘或是胡烈，要他们带人来保护皇上。\n&廖化\n我明白了，那么圣上就交给皇后您了。"]},{"op":"actor_move","args":[0,17,0,59,32,0]},{"op":"actor_select","args":[0,17,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&刘禅\n（朕从小就被赵叔叔保护，长大以后被\n相父保护，没想到现在年近六旬还是继续\n被人保护…）\n&刘禅\n（朕曾经也想要振作，想要保护别人，却\n总是什么也办不到。若是朕能够再振作一\n点，又怎么会变成这样的局面？）\n&张皇后\n皇上，已经过去的事情就算了，现在您\n还是蜀地九十四万军民的国君，打起精神\n来吧。\n&张皇后\n不用担心，就算是接下来要到洛阳，梓童\n也会陪您到底，就如同我老爹如何陪先帝\n那样。\n&刘禅\n皇后…"]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[2,65535,65535,27,65535]},{"op":"actor_appear","args":[258,54,84,1,10]},{"op":"actor_appear","args":[259,63,78,0,10]},{"op":"actor_appear","args":[260,60,43,2,10]},{"op":"actor_appear","args":[5,60,61,3,9]},{"op":"actor_appear","args":[4,68,61,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["生存的意义"]},{"op":"place_name","args":["成都城内"]},{"op":"dialog","args":["&句扶\n你想要做什么？你都已经多活这么多年了\n，为什么要在这个关头放弃？\n&宁随\n已经没有希望了，当这些乱兵冲进来的\n一刻，我们大汉已经没有复国的可能。\n不如一死以谢丞相。\n&宁随\n而且你也该明白，伯约在这种情况下是\n不可能生还的。\n&句扶\n难道你就这样放弃了？当初皇上投降的\n时候，大将他宁可放弃自己的名誉也要\n拚那一丁点复国的希望，而你呢？\n&句扶\n你是聪明人，又曾经是丞相看好的接班人\n，为什么在这时候却蠢成这样？\n&宁随\n事到如今，又能做什么？\n&句扶\n难道你认为这样就完了？天下还有很多\n地方不是司马家的，事情并没有结束！\n&宁随\n对呀…\n&句扶\n我们还是有复国的希望，哪怕是等到十年\n、二十年以后，只要我们把那希望的种子\n给洒下去，终有开花结果的一天。"]},{"op":"delay","args":[3]},{"op":"actor_face","args":[5,0,1]},{"op":"dialog","args":["&宁随\n到最后，我的智慧还远不如你，亏我还\n自诩是常败军的智囊。\n&宁随\n你说的没错，天下还没有被司马家完全\n拿去，我们还是有翻盘的机会。\n&宁随\n东有东吴，北有外族，南有南中，这些\n地方都不是司马家可以掌握的。\n&句扶\n果然聪明的人还是不一样，其实我刚才还\n完全没有想到这些…"]},{"op":"actor_appear","args":[1,96,59,3,0]},{"op":"actor_appear","args":[2,96,54,3,0]},{"op":"actor_move","args":[65535,1,0,86,59,3]},{"op":"actor_move","args":[65535,2,0,86,54,3]},{"op":"actor_action","args":[1,0]},{"op":"actor_action","args":[2,0]},{"op":"dialog","args":["&杨兰\n总算看到你们了，现在局势很混乱，快点\n跟我们走。\n"]},{"op":"actor_face","args":[4,0,1]},{"op":"dialog","args":["&句扶\n杨姑娘？诸葛姑娘？你们怎么会在这里？\n&诸葛果\n详细的情形等稍后再说…请问主公呢？\n&宁随\n他正在别的地方，似乎已经和张翼将军\n一起逃出去了。"]},{"op":"actor_face","args":[4,0,3]},{"op":"dialog","args":["&句扶\n（你为什么要骗她们？）\n&宁随\n（我不想扼杀她们的心。）\n&杨兰\n这样…那就快走吧…\n&诸葛果\n………"]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[2,65535,65535,29,65535]},{"op":"actor_appear","args":[1,48,36,2,0]},{"op":"actor_appear","args":[5,53,36,2,0]},{"op":"actor_appear","args":[4,58,36,2,0]},{"op":"actor_appear","args":[2,53,43,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["姜维之妻"]},{"op":"place_name","args":["成都 城门"]},{"op":"dialog","args":["&杨兰\n听我说，如果再继续这样下去，恐怕我们\n根本没有机会逃出成都。\n&杨兰\n不如让我留下来抵挡敌军，这样至少\n你们三人可以脱身。\n&句扶\n虽然你很厉害，但不代表可以对付这么多\n敌兵呀…\n&杨兰\n我可是一骑当千，三国无双，这点敌兵\n不需要为我担心。\n&宁随\n你要骗骗句扶或许还可以，但是要骗我或\n是诸葛姑娘就不行了。\n&诸葛果\n想要宣称自己是主公的妻子，这样贼兵就\n会忙著杀你而让我们逃走…"]},{"op":"actor_action","args":[4,2]},{"op":"dialog","args":["&句扶\n开什么玩笑呀！我怎么可能让你做这种\n事情？\n&杨兰\n还有其他办法吗？连你旁边两个聪明人都\n想不出来了，你又想得到？\n&句扶\n大不了和贼军拚了！你舍弃自己故乡，和\n我们同甘共苦这么多年，现在怎么能让你\n牺牲？"]},{"op":"actor_action","args":[4,0]},{"op":"dialog","args":["&杨兰\n我也不想就这样死呀！但是如果只牺牲\n我一个人就可以换得大家的生还，我又\n能做什么选择？\n&诸葛果\n这…让果来代替呢？\n&杨兰\n只有你才认识五斗米道的人吧。你死了，\n谁又可以带路？\n&杨兰\n还有，平常你总是称我为主母，现在就让\n我来命令你，赶快带走这些人！\n&诸葛果\n………\n&杨兰\n难道你还想违抗命令？\n&诸葛果\n我知道了…\n&宁随\n其实应该让我这个老人先死的，本来早在\n三十多年前，我就该被丞相处死。\n&杨兰\n人家可对你这个老头没兴趣呢！\n&杨兰\n快走吧…这些年来，和你们相处，真的\n很快乐…我是说真的…"]},{"op":"actor_action","args":[1,6]},{"op":"dialog","args":["&诸葛果\n主母，永别了。\n&杨兰\n是呀，万一姜维逃出来的时候，请代替我\n揍他，知道吗？\n&诸葛果\n我明白了。"]},{"op":"actor_action","args":[1,0]},{"op":"actor_move","args":[65535,4,0,50,36,3]},{"op":"delay","args":[0]},{"op":"actor_move","args":[65535,4,0,50,22,0]},{"op":"actor_move","args":[65535,5,0,50,36,3]},{"op":"delay","args":[0]},{"op":"actor_move","args":[65535,5,0,50,22,0]},{"op":"actor_move","args":[65535,1,0,50,22,0]},{"op":"actor_select","args":[0,1,0,0,0,0,6]},{"op":"actor_select","args":[0,4,0,0,0,0,6]},{"op":"actor_select","args":[0,5,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&杨兰\n其实我只是想要这么一次而已，就算是\n假的也好。\n&杨兰\n至少在这一刻，我和那尹香可是平起\n平坐的。"]},{"op":"actor_face","args":[2,0,2]},{"op":"delay","args":[3]},{"op":"dialog","args":["&士兵02\n前面挡著的这个女人是谁？\n&杨兰\n我是大汉大将军姜维的正妻杨兰。\n&士兵03\n是那个把我们主帅害得很惨的姜维的\n妻子？\n&士兵02\n宰了她！\n&士兵03\n我要活剥她的皮！"]},{"op":"actor_action","args":[2,1]},{"op":"dialog","args":["&杨兰\n看来，这些人似乎不会让我好死呢，\n呵呵呵…\n&杨兰\n（后悔吗？不，我不后悔，这三十多年\n真的很快乐。）\n&杨兰\n（有可以思慕的人，有患难与共的伙伴，\n还有遥不可及的奋斗目标，这样的人生\n又还有什么要求的？）\n&杨兰\n（对了，为什么我到现在才想起来，\n当时汉人屠杀我部落时，那个背著同伴\n放走我的人真的好像姜维…）"]},{"op":"delay","args":[3]},{"op":"dialog","args":["姜维遇害的同时，他的妻子也同样被乱兵\n所杀。但是却没有人知道，姜维这个妻子\n的真实身分…"]},{"op":"fade_in","args":[]},{"op":"delay","args":[3]},{"op":"change_scene","args":[2,65535,65535,71,65535]},{"op":"actor_appear","args":[258,45,48,2,0]},{"op":"actor_appear","args":[259,50,48,2,0]},{"op":"actor_appear","args":[260,55,48,2,0]},{"op":"actor_appear","args":[261,60,48,2,0]},{"op":"actor_appear","args":[262,65,48,2,0]},{"op":"actor_appear","args":[569,55,53,2,0]},{"op":"actor_appear","args":[726,53,64,0,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["成都 西山"]},{"op":"title_text","args":["五斗米道"]},{"op":"actor_action","args":[569,2]},{"op":"dialog","args":["&武官\n快点把人交出来！别以为我没看见你放\n那些蜀将进山里。\n&武官\n贼首姜维和他妻子都已经死在我们手上\n，我们要斩草除根，永绝后患。"]},{"op":"actor_action","args":[569,0]},{"op":"dialog","args":["&范长生\n你知道这里是哪里？\n&武官\n是谁的地盘？\n&范长生\n我们五斗米道在这里立足了数十年，没有\n人敢踏进这座山里一步，难道你们有这个\n勇气踏进来？\n&武官\n还不是妖道！弟兄们，咱们冲进去！\n&步兵1\n我也是五斗米道的鬼卒…\n&步兵2\n我爹过去也是汉中五斗米道的鬼卒…\n&范长生\n我们蜀地五斗米道，光信众就超过十万，\n只是我们不喜欢干涉世事。\n&范长生\n如果你们不踏进来，我也不会去干涉\n你们外面的事情，好好想清楚吧。\n&武官\n（五斗米道好像真的不好惹。算了，反正\n对付五斗米道也不是我这种下级士官能做\n的事。）\n&武官\n哼！撤退！"]},{"op":"actor_move","args":[0,569,0,55,5,0]},{"op":"actor_move","args":[0,258,0,55,5,0]},{"op":"actor_move","args":[0,259,0,55,5,0]},{"op":"actor_move","args":[0,260,0,55,5,0]},{"op":"actor_move","args":[0,261,0,55,5,0]},{"op":"actor_move","args":[0,262,0,55,5,0]},{"op":"actor_select","args":[0,569,0,0,0,0,6]},{"op":"actor_select","args":[0,258,0,0,0,0,6]},{"op":"actor_select","args":[0,259,0,0,0,0,6]},{"op":"actor_select","args":[0,260,0,0,0,0,6]},{"op":"actor_select","args":[0,261,0,0,0,0,6]},{"op":"actor_select","args":[0,262,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&范长生\n（呼…为了保护这些蜀将，居然破例和\n外界冲突了。）\n&范长生\n（不过，我们五斗米道也很难在这乱世中\n独善其身，或许有一天得加入这样的混战\n吧。）"]},{"op":"actor_appear","args":[1,37,82,0,0]},{"op":"actor_move","args":[0,1,0,53,69,0]},{"op":"actor_action","args":[1,0]},{"op":"actor_face","args":[726,0,2]},{"op":"dialog","args":["&范长生\n刚才的话，你都听到了？姜维已经不在\n人世了…\n&诸葛果\n主公本来就不可能逃过这一劫，他为了\n取得钟会信任，一直都待在他身边。\n&范长生\n我也不是不知道你对姜维的感情，这个\n时候你实在应该大哭一场。\n&诸葛果\n笑也一生…\n&范长生\n别对我说这种话，你难道过去都这样压抑\n自己的感情？现在你也该学会放下这一切\n，好好做自己吧。"]},{"op":"actor_face","args":[1,3,2]},{"op":"dialog","args":["&诸葛果\n呜…呜…哇哇哇哇哇…\n&范长生\n（连这样坚强的女子都为他哭泣，到底\n姜维是何方神圣？只可惜我没有机会和\n他见面了。）"]},{"op":"fade_in","args":[]},{"op":"delay","args":[3]},{"op":"change_scene","args":[2,65535,65535,57,65535]},{"op":"actor_appear","args":[137,66,50,3,0]},{"op":"actor_appear","args":[138,53,50,1,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["曹魏军军营"]},{"op":"title_text","args":["暗杀之谋"]},{"op":"dialog","args":["&卫瓘\n（钟会伏诛虽然是好事，但是邓艾这边\n可就…）\n&卫瓘\n（说什么我也和钟会一起陷害过邓艾\n，要是他回复自由身，我可有数不尽\n的麻烦。）\n&田续\n请问监军找末将有何事？\n&卫瓘\n想不想要报仇？\n&田续\n末将不是很明白您的意思。\n&卫瓘\n我听说邓艾在江油说要诛杀你，还让你\n混在步兵的队伍中羞辱你。\n&卫瓘\n现在有个机会可以让你报复江油那次的\n羞辱。"]},{"op":"actor_action","args":[137,6]},{"op":"dialog","args":["&田续\n末将该怎么做？\n&卫瓘\n钟会被杀，现在邓艾的部众认为邓艾一定\n可以沉冤得雪，所以跑去接他了。\n&卫瓘\n单靠师纂的部队，恐怕会让邓艾逃脱。\n&田续\n所以大人要我去支援，继续押送邓艾？\n&卫瓘\n邓艾部众一定会有激烈抵抗，有抵抗就会\n有死伤，而刀剑又不长眼…\n&田续\n我明白了，末将一定照办！\n&卫瓘\n（邓艾，你也别怨我，想要你死的人实在\n太多了，说不定连相国他也不希望你活著\n呀。）"]},{"op":"fade_in","args":[]},{"op":"delay","args":[3]},{"op":"change_scene","args":[2,65535,65535,72,65535]},{"op":"actor_appear","args":[106,52,72,0,0]},{"op":"actor_appear","args":[645,50,76,0,0]},{"op":"actor_appear","args":[105,55,76,0,0]},{"op":"actor_appear","args":[258,45,76,0,0]},{"op":"actor_appear","args":[259,55,76,0,0]},{"op":"actor_appear","args":[260,44,44,2,0]},{"op":"actor_appear","args":[261,49,44,2,0]},{"op":"actor_appear","args":[262,54,44,2,0]},{"op":"actor_appear","args":[263,59,44,2,0]},{"op":"actor_appear","args":[264,64,44,2,0]},{"op":"actor_appear","args":[265,44,39,2,0]},{"op":"actor_appear","args":[266,49,39,2,0]},{"op":"actor_appear","args":[267,54,39,2,0]},{"op":"actor_appear","args":[268,59,39,2,0]},{"op":"actor_appear","args":[269,64,39,2,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["绵竹附近"]},{"op":"title_text","args":["重获自由"]},{"op":"dialog","args":["&步兵3\n快点放了太尉！\n&师纂\n你们这些人是想造反了吗？难道不知道我\n是益州刺史，是奉朝廷之命押邓艾回洛阳\n的人？\n&邓艾1\n哈哈哈哈哈…看来是钟会那个狗贼造反\n被杀了，反贼终究是没有好下场的。\n&步兵4\n不错，反贼钟会已经伏诛，如此更可证明\n太尉的清白，所以我们要把他带回成都。\n&师纂\n胡说！我什么命令都没有接到。\n&邓忠\n你这家伙，快点认命放了我们吧！\n&邓艾1\n不用了，反正这家伙和我们陇西军没有\n什么渊源，加上平日对士卒又刻薄寡恩，\n士兵根本不会听他的。\n&邓艾1\n我们就在这里看戏就好了，看一个愚人\n是怎么样死的。"]},{"op":"delay","args":[3]},{"op":"dialog","args":["裴松之引《魏晋世语》说，师纂被愤怒的\n陇西军杀害，因为他对人性急又少恩惠，\n死时据说身上没有一处皮肤是完好的。"]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[2,65535,65535,72,65535]},{"op":"actor_appear","args":[645,53,49,2,0]},{"op":"actor_appear","args":[105,58,49,2,0]},{"op":"actor_appear","args":[260,44,44,2,0]},{"op":"actor_appear","args":[261,49,44,2,0]},{"op":"actor_appear","args":[262,54,44,2,0]},{"op":"actor_appear","args":[263,59,44,2,0]},{"op":"actor_appear","args":[264,64,44,2,0]},{"op":"actor_appear","args":[265,44,39,2,0]},{"op":"actor_appear","args":[266,49,39,2,0]},{"op":"actor_appear","args":[267,54,39,2,0]},{"op":"actor_appear","args":[268,59,39,2,0]},{"op":"actor_appear","args":[269,64,39,2,0]},{"op":"actor_appear","args":[138,52,72,0,0]},{"op":"actor_appear","args":[282,40,76,0,0]},{"op":"actor_appear","args":[283,45,76,0,0]},{"op":"actor_appear","args":[284,50,76,0,0]},{"op":"actor_appear","args":[285,55,76,0,0]},{"op":"actor_appear","args":[286,60,76,0,0]},{"op":"actor_appear","args":[287,65,76,0,0]},{"op":"actor_appear","args":[288,70,76,0,0]},{"op":"actor_appear","args":[289,40,80,0,0]},{"op":"actor_appear","args":[290,45,80,0,0]},{"op":"actor_appear","args":[291,50,80,0,0]},{"op":"actor_appear","args":[292,55,80,0,0]},{"op":"actor_appear","args":[293,60,80,0,0]},{"op":"actor_appear","args":[294,65,80,0,0]},{"op":"actor_appear","args":[295,45,85,0,0]},{"op":"actor_appear","args":[296,50,85,0,0]},{"op":"actor_appear","args":[297,55,85,0,0]},{"op":"actor_appear","args":[306,60,85,0,0]},{"op":"actor_appear","args":[307,50,90,0,0]},{"op":"actor_appear","args":[308,55,90,0,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["绵竹附近"]},{"op":"title_text","args":["邓艾之死"]},{"op":"actor_action","args":[645,2]},{"op":"dialog","args":["&邓艾1\n田续，这是什么意思？"]},{"op":"actor_action","args":[645,0]},{"op":"dialog","args":["&田续\n什么意思？你应该比我还清楚。\n&邓艾1\n卫瓘这家伙一定是怕我回成都之后向他\n报复，所以派你在这个地方阻截我。\n&田续\n我奉监军之命，特来拿邓艾父子归案，\n如果有抵抗者，定斩不赦。\n&邓忠\n爹，事到如今，就算跟他回去也难逃\n一死。\n&邓艾1\n没错，卫瓘那家伙不会放过我的…等一下\n…事情不是这样的…"]},{"op":"actor_face","args":[105,0,3]},{"op":"dialog","args":["&邓忠\n什么？！\n&邓艾1\n如果相国他不想我死，他绝对会保护我，\n至少会让卫瓘这种谨慎小心的人知道杀我\n的后果。\n&邓艾1\n然而卫瓘却如此有恃无恐，看来真正想要\n我死的可不见得只有卫瓘…\n&邓忠\n爹，司马家的天下有一半是您打下来的，\n为什么他要这样对您？\n&邓艾1\n狡兔死，良狗亨；高鸟尽，良弓藏；\n敌国破，谋臣亡。\n&邓艾1\n我明明知道文种、淮阴的下场，却还是\n走上和他们相同的道路。"]},{"op":"actor_face","args":[105,0,2]},{"op":"dialog","args":["&邓忠\n爹，这时候就该带著笑容，用手上的刀剑\n和敌人做最后一搏。\n&邓忠\n爹，希望我们来生还能当父子。\n&步兵3\n我们陇西部队也希望来生能当你们部属。\n&邓艾1\n有你们这样的部下，我邓艾可是虽死而\n无憾！"]},{"op":"delay","args":[3]},{"op":"dialog","args":["重获自由的邓艾父子在绵竹被追上来的\n田续斩杀。不久后，司马昭也把邓艾留\n在洛阳的其他儿子全数斩杀，\n\n并且把邓艾的妻子和孙儿都流放到西城。\n其后朝中屡有为邓艾平反之议，然而却\n直到公元二七三年，\n\n司马炎才应段灼、樊建等人所言，正式为\n邓艾平反。将其孙邓朗拔擢为郎中。\n\n\n邓艾建立旷世奇功，却蒙受如此大冤，而\n后世也没有多少人为他抱屈，令人不胜唏\n嘘。"]},{"op":"delay","args":[3]},{"op":"fade_in","args":[]},{"op":"delay","args":[3]},{"op":"change_scene","args":[2,65535,65535,57,65535]},{"op":"actor_appear","args":[111,66,50,3,0]},{"op":"actor_appear","args":[137,53,50,1,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["曹魏军军营"]},{"op":"title_text","args":["杜预之怒"]},{"op":"delay","args":[3]},{"op":"actor_action","args":[137,6]},{"op":"dialog","args":["&卫瓘\n我听说您在大家面前，批评我的行为。\n我也知道错了，请接受我的道歉。\n&杜预\n哼！你曾祖卫暠是个令人尊敬的儒学大家\n，你父亲卫觊也声誉卓著。\n&杜预\n结果你既没有品德，又不能用正直的作为\n作部下表率，用公权力满足私欲，你简直\n是丢你河东卫家的脸！\n&卫瓘\n唉…我也是不得已的，要知道想他死的\n可不只有我而已呀。\n&杜预\n你好自为之吧！\n&杜预\n（我又何尝不知相国也在默许这样的行为\n，其实最想杀邓艾的恐怕就是他吧。）"]},{"op":"fade_in","args":[]},{"op":"delay","args":[3]},{"op":"change_scene","args":[2,65535,65535,48,65535]},{"op":"actor_appear","args":[21,51,33,2,0]},{"op":"actor_appear","args":[231,39,48,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["永安之危"]},{"op":"place_name","args":["永安城议事厅"]},{"op":"actor_face","args":[231,6,0]},{"op":"dialog","args":["&杨宗\n成都陷落的消息现在已经传得到处都是\n，如果我们不采取行动的话，永安可是\n非常危险。\n&罗宪\n那么就把那个散播消息的人杀了，这样\n应该可以稍微撑一段时间。\n&杨宗\n事情可没有这么简单吧，你我都知道成都\n不但沦陷，而且不久前还发生钟会叛乱，\n甚至连大将军都死在那场乱事。\n&罗宪\n我知道…一时之间我也拿不定主意。\n&杨宗\n更可恶的应该是东吴，看那步协率领的\n军队，名义上是要增援，实际上却是想\n偷袭我们。\n&罗宪\n真给右大将军说对了，东吴和我们本为\n唇齿相依之邦，没想到不同情我们的苦难\n，还在这时候背弃盟誓，偷袭我们。\n&杨宗\n从现实角度来看，大汉已亡，东吴大概\n也撑不了多久，干嘛向他们投降。"]},{"op":"actor_action","args":[231,0]},{"op":"actor_action","args":[21,0]},{"op":"dialog","args":["&罗宪\n好，就让我来痛击他们。\n&罗宪\n命你突围北上，去找魏军支援，就说我们\n永安已经是他们领土，请他们增援。"]},{"op":"actor_action","args":[21,0]},{"op":"dialog","args":["&杨宗\n那可不够，还得准备文武官员的印信，\n还有人质才行。人质最好要美一点的…\n&罗宪\n你该不会中途想做什么吧？\n&杨宗\n我杨宗可以以人格保证，绝对清廉可靠。\n&罗宪\n算了吧，你和关索、霍弋并称三大损友，\n整个大汉何人不知？"]},{"op":"delay","args":[3]},{"op":"dialog","args":["罗宪率领永安区区两千人军队，先是大破\n步协军队，又挡住陆抗攻势超过半年。终\n于在半年后等到胡烈的援军，\n\n永安因而解围。司马昭嘉许罗宪的忠勇\n，任命他留永安原官，加号陵江将军，\n封万年亭侯。"]},{"op":"fade_in","args":[]},{"op":"delay","args":[3]},{"op":"change_scene","args":[2,65535,65535,24,65535]},{"op":"actor_appear","args":[13,58,54,2,0]},{"op":"actor_appear","args":[16,54,59,0,0]},{"op":"actor_appear","args":[20,62,59,0,0]},{"op":"actor_appear","args":[18,54,64,0,0]},{"op":"actor_appear","args":[28,58,64,0,0]},{"op":"actor_appear","args":[11,63,64,0,0]},{"op":"if","cond":"test_flags","args":[[],[907]],"end":364},{"op":"actor_appear","args":[22,58,59,0,0]},{"op":"endif","args":[]},{"op":"fade_out","args":[]},{"op":"title_text","args":["南中动向"]},{"op":"place_name","args":["南中 蜀汉军军营"]},{"op":"dialog","args":["&霍弋\n这件事情关系重大，我也不敢随便作主，\n所以请大家一起来商量一下。\n&霍弋\n刚才接到成都那边的消息，因为钟会叛乱\n，整个成都成为战场，死伤无数。\n&霍弋\n其中大将军和左车骑将军、蒋护军兄弟、\n太子等人都已经确认罹难了。\n&赵统\n怎么会这样？！\n&刘敏\n我认为大将军早就有预感事情会变成这样\n，所以才会要我们先逃到南中去。\n&刘敏\n只可叹我没有保护好蒋家两兄弟，这样我\n怎么去面对外兄？\n&关索\n伯约他还真傻，他失败后造成这样的灾难\n，恐怕后世的人会一直嘲笑他。\n&霍弋\n还有一件对关将军来说很不幸的消息，\n我听说成都关家被魏将庞会趁乱灭门了。\n&关索\n什么？！庞会？难道是庞德的儿子？\n&霍弋\n是的。\n&关索\n该死…我居然没有想到这一点，庞德的\n儿子居然会跟著来进攻？"]},{"op":"dialog","args":["&赵统\n因为曹贼的侵攻，我们每个人几乎都失去\n了自己的亲人。不过我们没有时间悲伤下\n去了。\n&关索\n可恶呀…二哥，我居然没办法守住您的\n儿子…我到底在做什么？！"]},{"op":"actor_face","args":[20,0,3]},{"op":"dialog","args":["&花鬘\n关索，你冷静点…现在你是关家最后的\n血脉，一定要保重自己的啦。\n&关索\n我知道，我也知道…\n&孟琰\n（看来俺真是一点机会也没有，这该死的\n关索真是人在福中不知福。）"]},{"op":"actor_face","args":[20,0,0]},{"op":"if","cond":"test_flags","args":[[],[907]],"end":375},{"op":"dialog","args":["&张嶷\n（如果当初我能再坚持一点，率军去阴平\n小道埋伏，说不定就没有今天这样的灾祸\n了。）"]},{"op":"endif","args":[]},{"op":"dialog","args":["&霍弋\n我想到一个方式可以保护我们所有人的\n安全，只是不知道大家肯不肯接受。\n&霍弋\n南中地区对于贼人来说，山多崎岖，气候\n炎热，完全没有进攻的欲望。\n&霍弋\n如果我们能名义上投降他们，我想他们会\n因为考虑到治理的困难，让我们保有实质\n的独立性。\n&霍弋\n当然这计画需要南中大族的协力，不知道\n孟将军愿意协助我们吗？\n&孟琰\n我们孟氏一族一定会支持大汉政权的，\n这点请放心的啦。\n&孟琰\n其他大姓像是焦、雍、娄、爨、量、毛、\n李等也一定会配合的啦。"]},{"op":"delay","args":[3]},{"op":"dialog","args":["&赵统\n我同意，至少我们可以维持一个实质的\n大汉政权，也可以收容逃难的军民。\n&刘敏\n既然大将军都肯牺牲自己的名誉，我们又\n为什么不行。\n&霍弋\n那么我就向曹贼递降书了。"]},{"op":"delay","args":[3]},{"op":"if","cond":"test_flags","args":[[],[907]],"end":382},{"op":"dialog","args":["&张嶷\n等一下，我听说司马家因为自诩是儒学\n名家，所以特别喜欢忠孝节义的故事。\n&张嶷\n不如我们也来编个让司马昭爽孜孜的故事\n吧。"]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[907],[]],"end":385},{"op":"dialog","args":["&霍弋\n（等一下，听说司马家因为自诩是儒学名\n家，所以特别喜欢忠孝节义的故事。）\n&霍弋\n（不如我们也来编个让司马昭爽孜孜的故\n事吧。）"]},{"op":"endif","args":[]},{"op":"delay","args":[3]},{"op":"dialog","args":["霍弋递降书，上书提到：“我曾经听说，\n人生在世，有三位君长，父、母、君王，\n而事奉他们的道理，完全一样。\n\n三者有难，则为他们效死。而今，我的国\n家败亡，主上归附；牺牲性命已无对象。\n所以向陛下投靠，忠心不二。”\n\n司马昭嘉许霍弋的节操，任命他当南中\n都尉，对南中之事不加干涉。"]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[2,65535,65535,2,65535]},{"op":"actor_appear","args":[55,56,58,0,0]},{"op":"actor_appear","args":[647,56,51,2,0]},{"op":"place_name","args":["行馆"]},{"op":"title_text","args":["预言成真"]},{"op":"fade_out","args":[]},{"op":"dialog","args":["&陈寿\n老师，没想到您预言的那么准，当初\n在宫门留下的十二字真言居然成真，\n大汉果然在一年后灭亡了。\n&谯周\n这没什么，不过是从杜琼先生的言辞去\n推论的，并没什么创新的地方。\n&陈寿\n不，这还是很厉害呀，不畏惧像张裕那样\n的下场，拥有说出实话的勇气实在是非常\n可贵。\n&谯周\n不过，后人会怎么看我呢？认为我早就\n已经和大魏互通声息？\n&陈寿\n老师，明明就不是这样，您是热爱益州\n这片土地才会说出这些话，不是吗？\n&谯周\n我认为天命归大魏，所以不认同姜维出兵\n造成我益州人伤亡，那只不过是徒劳无功\n的举动而已，人终究胜不了天命。\n&陈寿\n老师说得是，粗有文武，志立功名，\n而玩众黩旅，明断不周，终致陨毙。\n&谯周\n是呀，志立功名，玩众黩旅，明断不周\n，终致陨毙…"]},{"op":"delay","args":[3]},{"op":"dialog","args":["谯周因劝后主刘禅降，遂被封为阳城亭侯\n，迁骑都尉，最后被封散骑常侍，于公元\n二七零年冬天去世。\n\n谯周精通六经与天文现象，并以反对姜维\n出兵的“仇国论”闻名于后世。他一连串\n强调曹魏消灭蜀汉的言论，\n\n究竟是真的相信这样的占卜结果，还是为\n别有用意则不得而知。只是他的劝降确实\n也象徵部分益州人对蜀汉政权的离心。\n\n他的弟子陈寿后来并没有被晋朝重用\n，不过他编写的《三国志》至今仍四处\n流传。"]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[2,65535,65535,64,65535]},{"op":"actor_appear","args":[17,63,54,0,0]},{"op":"title_text","args":["老将之死"]},{"op":"place_name","args":["行馆"]},{"op":"fade_out","args":[]},{"op":"dialog","args":["&廖化\n德艳…\n&宗预\n我活到这把岁数，就算死也算是天寿。\n但以这样的方式死去，还是很不甘心。\n&廖化\n我的身体也一天不如一天，恐怕是撑不到\n洛阳了。\n&宗预\n亡国之臣本来就没有这么好当，特别像\n我们这些经历过开国时期的人，哪受得\n了这样的打击。\n&廖化\n真的好痛苦，早知道当时就和伯约一起\n战死算了。\n&宗预\n唉…要是我们当初能齐心协力，又怎么会\n落到这样的下场？毁掉大汉的，不是邓艾\n，而是我们自己呀。\n&廖化\n或许你说得对吧，但现在后悔也来不及。\n只有到那边再向伯约和关将军谢罪。\n&宗预\n（伯苗，我辜负了你的期待，还眼睁睁\n看著大汉灭亡。有著这样罪孽的我，还有\n机会到和你一样的地方？）"]},{"op":"delay","args":[3]},{"op":"dialog","args":["公元二六四年初，镇军大将军宗预和\n右车骑将军廖化在被护送前往洛阳的\n途中病逝。"]},{"op":"fade_in","args":[]},{"op":"delay","args":[3]},{"op":"play_music","args":[208,0]},{"op":"change_scene","args":[2,65535,65535,73,65535]},{"op":"actor_appear","args":[27,43,52,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["恩仇消逝"]},{"op":"place_name","args":["雍州"]},{"op":"delay","args":[3]},{"op":"dialog","args":["&马岱\n到最后，不但伯约死了，居然连杨阜的\n女儿都死了。\n&马岱\n当大家都在为了心中的理想而奋斗，\n我却还是停留在原地，只是为了仇怨\n而战。\n&马岱\n到最后什么都没有得到，不但赔光了弟兄\n，还做出许多后悔至今的事。"]},{"op":"actor_action","args":[27,6]},{"op":"dialog","args":["&马岱\n伯约，接下来我那残余不多的人生将为\n马家的存续而活。\n&马岱\n我会告诉他们这些年发生的事情，让他们\n知道永远不要再犯下自己曾犯的错误。"]},{"op":"delay","args":[3]},{"op":"play_music","args":[8,255]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[2,65535,65535,1,65535]},{"op":"actor_appear","args":[10,53,60,1,0]},{"op":"actor_appear","args":[3,53,55,1,0]},{"op":"actor_appear","args":[8,53,50,1,0]},{"op":"actor_appear","args":[47,58,60,1,0]},{"op":"actor_appear","args":[52,58,55,1,0]},{"op":"actor_appear","args":[48,58,50,1,0]},{"op":"actor_appear","args":[257,63,55,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["降伏的勇气"]},{"op":"place_name","args":["剑门关军营"]},{"op":"delay","args":[3]},{"op":"dialog","args":["&阎宇\n长元，你是说要我们投降？\n&樊建\n成都发生的事情，或许你们或多或少都有\n耳闻了。大将军的复国计画失败，已经以\n身殉国了。"]},{"op":"actor_action","args":[3,2]},{"op":"dialog","args":["&柳隐\n不！不！为什么会这样？为什么老大苦了\n一辈子，最后还给他这样难堪的结局？"]},{"op":"actor_action","args":[3,0]},{"op":"dialog","args":["&樊建\n柳将军，我希望你能冷静一点，现在就算\n是悲伤或发怒都无济于事。\n&樊建\n这里有将近四万的军队，如果不赶快表明\n态度，恐怕成都和长安两地的军队将发动\n攻击，到时就来不及了。\n&王含\n所以要我们表明恭顺的态度，让那些贼军\n不至于把我们当敌人？真是屈辱到极点。\n&向充\n我们的士兵都还有斗志，加上大将军遇害\n，一定能发挥更强的战斗力。\n&来忠\n就算战死，也好过当投降的亡国奴！\n&阎宇\n要我投降，比杀了我还痛苦，这种事情\n实在是做不到。\n&王含\n要死就死，大汉臣子有哪个怕死的？\n&樊建\n你们不要再执迷不悟了！眼下四万将士的\n性命操在你们手上，不要再说这些不负责\n任的话了。\n&柳隐\n我认为你说的有道理。虽然我满腔的悲愤\n，但是也不能不考虑到老大要我们留在这\n里的用意。"]},{"op":"delay","args":[3]},{"op":"dialog","args":["&柳隐\n因为这场战争死亡的人已经够多了，难道\n大家还想要继续制造死伤才满意？想想这\n四万名弟兄都有亲人…"]},{"op":"actor_action","args":[257,6]},{"op":"dialog","args":["&樊建\n各位，投降是屈辱，需要比战死更大的\n勇气，拜托你们就听我这一次吧。\n&柳隐\n（老大，其实我是已经对这个政权心灰\n意冷了，在你死以后，我没有理由再为\n这个政权和昏君卖命。）\n&向充\n（我知道柳将军在想什么，但是他想的\n事情也不无道理，长久以来我们的奋斗\n是为了什么？得到的又是什么？）\n&来忠\n（个人的荣辱和四万名弟兄的生命，轻重\n可是一目瞭然。我已经制造了那么多的罪\n孽，又岂能在现在多加一笔？）"]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[2,65535,65535,44,65535]},{"op":"actor_appear","args":[130,51,35,2,0]},{"op":"actor_appear","args":[24,39,48,1,0]},{"op":"actor_appear","args":[103,64,48,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["乱事终结"]},{"op":"place_name","args":["长安城议事厅"]},{"op":"actor_face","args":[103,6,0]},{"op":"dialog","args":["&裴秀\n一切就如同相国所料，钟会造反失败被杀\n，邓艾也死在这场乱事中。\n&裴秀\n（钟会果然死了…也不枉费我让邵悌等人\n不断散布你会造反的传言，也不枉费我\n推荐卫瓘来盯死你的用心。）\n&裴秀\n（不过，我的计画虽然周全，但最后要\n成功还是得要你自己造反呀。）\n&裴秀\n（聪明一世的你到最后就毁在自己的\n野心上，你也怪不了我。）\n&司马昭\n公主这招震山敲虎果然厉害，一口气解决\n掉两个心腹大患。\n&曹绫\n（果然失败了，本来只要钟会能够夺取\n手上军队的指挥权，或是直接用蜀将，\n在战场上交锋还有一丁点机会取胜。）\n&曹绫\n（钟会想必在最后关头没有狠下心诛杀手\n下将领才会造成这样的结果，像他这样\n聪明的人会犯下这种错误，岂非天意？）\n&曹绫\n（既然连这最后的计策也失败，看来\n司马昭要篡位的脚步已经是挡不住了。）\n&曹绫\n那个…姜维他的状况如何？"]},{"op":"actor_face","args":[103,0,3]},{"op":"dialog","args":["&裴秀\n姜维煽动钟会谋反，跟著钟会一起被斩杀\n…据说我军因为愤恨姜维阴谋害他们，\n所以连他的妻子一起被杀。\n&曹绫\n什么？！姜维他死了…妻子…又是怎么\n回事？\n&司马昭\n公主怎么慌乱成这样？你怎么会这么重视\n那个人？\n&曹绫\n整个蜀地最大的支柱就是他，得到他更\n胜过得到蜀地。\n&司马昭\n说得也是，比起心怀诡诈的钟会或是难以\n驾驭的邓艾，这个人确实是我梦寐以求的\n大将。\n&曹绫\n我是为了大魏痛失一个人才而悲伤。少了\n他，或许灭吴还得多等一段时间。\n&司马昭\n公主爱才的表现还真像是武皇帝…\n&曹绫\n（我为什么说得出这种话来？明明现在我\n心痛得要命…今天能站在这里全都是你的\n支持，然而你居然先走一步？）\n&曹绫\n（想要不顾一切痛哭，但是在敌人眼前却\n不可以掉下一滴眼泪，这真的好痛苦。）"]},{"op":"delay","args":[3]},{"op":"actor_appear","args":[570,51,98,0,0]},{"op":"actor_move","args":[0,570,0,51,48,0]},{"op":"actor_action","args":[570,6]},{"op":"dialog","args":["&文官\n因为这次灭蜀大功，圣上想要封您为晋王\n，请您即刻回洛阳接受册封。\n&司马昭\n嗯…我知道了。即刻启程回到洛阳。\n&司马昭\n（晋王也到手，接下来就是禅让了，一切\n总是进行得这么顺利。）\n&司马昭\n（只是不知道为什么，我却有种空虚感，\n莫非是因为邓艾、姜维等英雄都已经离世\n的关系？还是因为曹绫已经挡不住我？）\n&曹绫\n（纵然现在已经无法再有什么作为了，\n但我还是有可以努力的目标。至少在最后\n，帮曹家争取最后一点生存空间也好。）"]},{"op":"delay","args":[3]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[71]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,29,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二六四年三月十九日，曹魏皇帝曹奂封司马昭“晋王”，增加采邑十个郡。",1,0,1]},{"op":"delay","args":[3]},{"op":"caption","args":["两个月后，追封司马懿为“晋宣王”，司马师为“晋景王”。",1,1,1]},{"op":"delay","args":[3]},{"op":"caption","args":["此时，距离篡位只剩下一个步骤了。",0,0,1]},{"op":"fade_in","args":[]},{"op":"delay","args":[3]},{"op":"change_scene","args":[2,65535,65535,11,65535]},{"op":"actor_appear","args":[130,49,71,0,0]},{"op":"actor_appear","args":[100,36,45,1,0]},{"op":"actor_appear","args":[49,63,45,3,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[3]},{"op":"title_text","args":["乐不思蜀"]},{"op":"place_name","args":["洛阳相国府"]},{"op":"delay","args":[3]},{"op":"actor_face","args":[49,0,2]},{"op":"dialog","args":["&刘禅\n不知道晋王您今天要招待什么，还真让人\n期待呢。\n&司马昭\n孤似乎也邀请了安乐公你的旧属，怎么都\n没有跟著来？\n&刘禅\n他们怕触景生情，所以并没有前来。\n&贾充\n（晋王曾经对我说过，一个人没有灵性\n，居然能到如此地步，纵然诸葛亮也无法\n辅佐他长久不坠，更何况姜维。）\n&司马昭\n你是不是很想念巴蜀？\n&刘禅\n此间乐，不思蜀！"]},{"op":"fade_in","args":[]},{"op":"delay","args":[3]},{"op":"play_sound","args":[70]},{"op":"change_scene","args":[2,65535,65535,15,65535]},{"op":"actor_appear","args":[183,45,63,0,0]},{"op":"actor_appear","args":[186,45,46,2,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["东吴新君"]},{"op":"place_name","args":["建业 皇宫"]},{"op":"dialog","args":["&张布\n没想到陛下就这样走了…\n&濮阳兴\n因为蜀国灭亡，之后攻略永安不顺利，\n加上交州吕兴反叛，现在我们大吴真的\n很危险。\n&张布\n所以就算陛下用手指托我们拥立年幼的\n太子即位，我们也不可以轻易答应。这\n国家需要年长的君王。\n&濮阳兴\n可是一时之间我们到哪里去找年长的\n君王？大皇帝的皇子辈除了齐王孙奋\n这个声名狼藉的家伙以外，全都死光了。\n&张布\n皇孙的话，我一下子也想不到还有谁。"]},{"op":"delay","args":[3]},{"op":"actor_appear","args":[187,95,53,3,0]},{"op":"actor_move","args":[0,187,0,50,53,3]},{"op":"actor_action","args":[187,6]},{"op":"actor_face","args":[183,0,1]},{"op":"actor_face","args":[186,0,1]},{"op":"delay","args":[3]},{"op":"dialog","args":["&万彧\n在下倒是有个不错的人选可以推荐。\n&张布\n这不是左典军吗？\n&濮阳兴\n到底是什么人可以让你如此看重？\n&万彧\n乌程侯是故太子孙和之子，才能见识卓越\n，英明而有决断力，奉公守法，好学不倦\n。若说他像谁嘛…在下是想到一个人。\n&张布\n像何人？\n&万彧\n长沙桓王。"]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[4]},{"op":"change_scene","args":[2,65535,65535,10,65535]},{"op":"actor_appear","args":[79,51,53,1,0]},{"op":"actor_appear","args":[33,70,53,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["孙策再世"]},{"op":"place_name","args":["乌程 议事厅"]},{"op":"delay","args":[3]},{"op":"actor_action","args":[79,6]},{"op":"dialog","args":["&马扁\n恭喜皇上，贺喜皇上！左典军的游说\n似乎奏效了，马上就会有人来迎接您\n前往建业。\n&孙皓\n嗯…\n&马扁\n皇上您在想什么？是不是您手头的国务\n机要费不够用？如果是的话，就交给阿扁\n来张罗。\n&孙皓\n你们夷州人只会在意这点小事？\n&马扁\n偶们夷州是个鬼岛嘛，每个人都穷到没\n裤子穿，只可惜被圣朝带过来的人只剩下\n偶一个而已。\n&孙皓\n朕只是在想，蜀国灭亡，天下被魏国\n夺去三分之二会不会还让得不够多？\n&孙皓\n不久以后，魏国大概也会被司马家篡夺，\n到时候就是我和司马家的对决。\n&孙皓\n希望司马家不要轻敌，如果他们以为朕\n是刘禅之流，他们绝对会后悔的。"]},{"op":"actor_appear","args":[5,4,53,1,0]},{"op":"actor_move","args":[0,5,0,46,53,1]},{"op":"actor_face","args":[79,0,3]},{"op":"actor_action","args":[5,6]},{"op":"dialog","args":["&宁随\n在下丹阳刁玄…\n&孙皓\n丹阳？你的口音怎么不像是丹阳人。再说\n，你当朕没看过真的刁玄？他可是宣太子\n（孙登）的宾客。\n&宁随\n果然是眼光锐利，不愧是在下看上的\n英主。\n&宁随\n在下曾经听闻水镜先生司马徽与刘廙\n论运命历数，不知道陛下有没有兴趣\n知道？\n&孙皓\n请说。\n&宁随\n黄旗紫盖见于东南，终有天下者，\n荆、扬之君乎！\n&孙皓\n哈哈哈哈哈，荆扬之君吗？你这个假刁玄\n还真有意思，朕还想多听听你的话。\n&马扁\n（赶羚羊勒，哪冒出来一个死神棍抢了\n阿扁的饭碗。）\n&宁随\n（事情不会这样结束的，司马家不会这么\n容易就夺取天下的！）\n&宁随\n（丞相与伯约死后，我更要替他们发扬对\n抗司马家的遗志。即使让孙皓变成第二个\n秦皇也在所不惜！）"]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[9]},{"op":"if","cond":"comment","args":["吕布被缚"],"end":521},{"op":"endif","args":[]},{"op":"change_scene","args":[2,65535,65535,38,65535]},{"op":"actor_appear","args":[557,52,57,3,0]},{"op":"actor_appear","args":[136,45,57,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["匈奴之子"]},{"op":"place_name","args":["洛阳 质子府"]},{"op":"dialog","args":["&刘渊\n请问得到的答覆是？\n&王浑\n不行呀，朝中大臣们还是认为“非我族类\n，其心必异”，完全不打算给你机会。\n&刘渊\n这点我倒是不意外，毕竟我们匈奴人和\n汉人打了好几百年的仗，一时间要对我们\n委以重任，根本是不可能的事。\n&王浑\n那些人就是死脑筋，也不想想像你这样\n饱读诗书的人，哪里还是危险的蛮族。\n&王浑\n过去我爹一直称赞你是个人才，当面相见\n之后更觉得不得了。\n&王浑\n以你的学问和武艺，哪怕是洛阳的朝中\n文臣武将也没几个人是你的对手。\n&刘渊\n不用担心，日后还有得是机会。就算相国\n平灭巴蜀，作乱之人仍然存在呀。\n&刘渊\n看看河西的秃发鲜卑和江东的吴贼，只要\n他们还在，我又何愁没有表现机会？\n&王浑\n说得也是，到时我会向相国再次推荐你。\n&王浑\n（我们父子看的绝对没错，像这样杰出的\n人才，绝对不能让他跑掉。在我大魏失去\n邓艾之后，此人正是后继之人。）\n&刘渊\n（到了洛阳之后，才发现并州实在太渺小\n。我们匈奴人怎么可以只窝在那小小地方\n苟且偷生？）\n&刘渊\n（我们匈奴祖先和汉朝宗室约为兄弟，\n流有汉朝的血，实在应该继承汉室，和\n司马家一较高下。）\n&刘渊\n（我就在洛阳慢慢累积实力，结交名士。\n总有一天，我们匈奴人会再度重拾往日的\n光荣。）"]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[6]},{"op":"change_scene","args":[2,65535,65535,20,65535]},{"op":"actor_appear","args":[218,75,55,3,0]},{"op":"actor_appear","args":[648,62,45,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["鲜卑之王"]},{"op":"place_name","args":["河西鲜卑王营帐"]},{"op":"dialog","args":["&秃发机能\n听说蜀国灭亡了，想不到过去那个能以\n少数军队撼动整个魏国的小国，最终还\n是难逃灭亡的命运。"]},{"op":"dialog","args":["&若罗拔能\n这样看来，魏国的势力恐怕是无法憾动\n了。难道我们真的要像姚柯回那没出息\n的家伙那样，对魏国表示恭顺？"]},{"op":"dialog","args":["&秃发机能\n忘记汉人怎么对待外族？羌人被汉人屠杀\n，根本就是“绝其本根，不使能殖”，\n这些我们可是看得清清楚楚。"]},{"op":"dialog","args":["&若罗拔能\n所以说，大王应该是要反抗了？\n"]},{"op":"dialog","args":["&秃发机能\n我刚继承祖父的部族，势力还不完全\n稳固，一旦我稳固统治，也就是这些\n汉人的末日了。"]},{"op":"dialog","args":["&若罗拔能\n好呀！杀光汉人，还我河西！\n"]},{"op":"dialog","args":["&秃发机能\n呵呵呵…我倒要看看汉人有没有真正有\n骨气的将领敢和我对决。"]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[6]},{"op":"change_scene","args":[2,65535,65535,32,65535]},{"op":"actor_appear","args":[649,61,59,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["慕容鲜卑"]},{"op":"place_name","args":["辽东"]},{"op":"dialog","args":["&慕容涉归\n现在大魏独强已经是确定的事，看来我\n当初决定要把部族迁到辽东郡是正确的\n决定。\n&慕容涉归\n虽然比起当年轲比能威震各部和汉人对抗\n要逊色很多，但是想想他的悲惨下场，还\n是像我现在比较好。\n&慕容涉归\n靠著大魏“大单于”的封号，我才能和\n段氏、宇文氏等部相斗。\n&慕容涉归\n只是…万一哪天大魏或是取代他的中原\n王朝衰落，我还要继续低声下气？"]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[6]},{"op":"if","cond":"comment","args":["吕布被缚"],"end":555},{"op":"endif","args":[]},{"op":"change_scene","args":[2,65535,65535,20,65535]},{"op":"actor_appear","args":[582,74,54,3,0]},{"op":"actor_appear","args":[592,60,54,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["草付应王"]},{"op":"place_name","args":["羌王营帐"]},{"op":"dialog","args":["&姚柯回\n蒲怀归啊，原来是你。找本王有什么\n事情啊？"]},{"op":"dialog","args":["&氐族兵1\n我是代表我们蒲氏部族来向羌王您求\n和的。\n"]},{"op":"dialog","args":["&姚柯回\n你们氐奴哪有资格和我谈条件，要么就\n投降我，向我屈服。\n&氐族兵1\n我实在不懂羌王为什么要对我们追杀到底\n，帮著汉人屠杀我们氐族有什么好处？\n等到我们都死完了，接下来就轮到你。\n&姚柯回\n光冲著西羌都督这个官位就值得了。\n靠著这官位，我做什么都畅行无阻。\n&姚柯回\n更何况大魏对我这个叛服不定的人毫无\n信赖感，如果不做些表示，只怕到后来\n又把矛头对向我们。\n&氐族兵1\n那也不能就攻击我们呀，我们什么都\n没做，我们也是支持大魏的部族。\n&姚柯回\n怪就怪自己弱吧，蠢人！\n&氐族兵1\n你这样逼下去，是要逼到我们氐族人内迁\n到中原？\n&姚柯回\n那是你们的事。像你这种低下的氐奴，\n哪能明白我建国之志？"]},{"op":"dialog","args":["&姚柯回\n（现在最大的问题是，我何时能有个儿\n子？姚弋仲这个名字我为父早给你取好\n了，你快些降生吧。）"]},{"op":"dialog","args":["&氐族兵1\n（这羌人的嘴脸真令人讨厌。我发誓，我\n总有一天会让我们蒲氏部族爬到你们羌人\n头上来。）"]},{"op":"dialog","args":["&氐族兵1\n（你不是说我们弱小吗？那我就给我\n的儿子起个大气些的名字！嗯……就\n叫蒲洪好了。）"]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,23,65535]},{"op":"actor_appear","args":[4,34,48,1,0]},{"op":"actor_appear","args":[591,41,48,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["上党羯族"]},{"op":"place_name","args":["上党附近"]},{"op":"dialog","args":["&石周曷朱\n我认识的汉人中，就属你最有气魄。\n&石周曷朱\n只是像你这样的人，为什么没有入朝为官\n，而是跑到我们这贫穷的部落？\n&句扶\n事到如今我也不想隐瞒了，我是故汉将领\n，姓句名扶，字孝兴，而且也不是汉人。\n&石周曷朱\n賨人吗？原来如此。从这么远的地方过来\n，你也真是辛苦了。\n&句扶\n我浪迹天涯，就是为了找寻能够反抗魏国\n和司马家的人。\n&石周曷朱\n可惜你真的找错人了，我们羯族部落贫困\n无比，人丁也不旺，依附汉人都来不及了\n，哪有能力反抗。\n&句扶\n不，看到羯人在如此恶劣环境中还不屈\n不挠的精神，我认为我没有看错。\n&石周曷朱\n说真的，我也不是安于现状的人。资源被\n汉人掠夺殆尽不说，还不停抓我们的人去\n充丁，实在让人无法忍受。\n&句扶\n正是如此，如果我们不早点有所觉悟，\n只会永远被汉人牵著鼻子走。\n&石周曷朱\n你要是不嫌弃的话，我想和你结拜兄弟。\n&句扶\n结拜？\n&石周曷朱\n是呀，我还希望你指导我将来要出世的\n孩子，让他成为远超过我这无能老爹的\n大将。\n&句扶\n那还真是荣幸呀…如果可以的话，我可以\n帮忙取名吗？\n&石周曷朱\n当然可以，你想给他取什么名字？\n&句扶\n叫做石勒如何？既有勒马中原之意，也有\n将部络组织起来，勒以文明之意。\n&石周曷朱\n石勒…还挺威武的嘛…想不到你会对我这\n未出世的儿子有如此期待。\n&句扶\n（我看得没错，羯族有这个本事，虽说\n石周曷朱的格局不大，但如果说我好好\n培育下一代，说不定真的可以翻盘。）\n&句扶\n（到时候一定要好好告诉石勒曹操和\n司马懿的事情，让他能分辨什么样的人\n该尊敬，什么样的人该鄙视。）\n&句扶\n（抱歉了，既然大将已经不存在，我也\n没有必要再为汉人效力。今后的句扶将是\n一介賨人，永远不会回头了。）"]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[39]},{"op":"change_scene","args":[2,65535,65535,36,65535]},{"op":"actor_appear","args":[149,37,55,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["怨恨的种子"]},{"op":"place_name","args":["东莱王家"]},{"op":"dialog","args":["&王颀\n真令人感叹，和我同时平定蜀地的两位\n太守，不久后也都当到了州刺史。\n&王颀\n只有我还是停留在太守的等级，这就表示\n朝廷对我的态度就是这样。\n&王颀\n因为我效命过毌丘俭和邓艾这两名叛将，\n所以这辈子都无法翻身，就算我想要为国\n效命都难。"]},{"op":"dialog","args":["&王颀\n不过我一点也不后悔。毌丘将军和邓将军\n是我看过最有骨气和忠诚心的大将，比起\n当朝许多高官要伟大得多。\n&王颀\n既然朝廷还惦记著当年的事情，我也没有\n必要再为这种小鼻子小眼睛朝廷效力。\n&王颀\n就算日后边疆再闹得沸沸腾腾，我也不想\n再向当年出征高句丽一样披挂上阵了。"]},{"op":"dialog","args":["&王颀\n我的孙儿昨天才出生，希望他绝对不要\n像我一样当官，到最后才发现什么都是\n空的。\n&王颀\n只有靠著自己的本事，获得自己想要的\n东西，这才是真的。\n"]},{"op":"dialog","args":["&王颀\n这孩子的哭声与双眼异于常人，或许\n他还有能力颠覆这个政权也不一定。"]},{"op":"dialog","args":["&王颀\n对了，还没给他起名字呢……就叫王弥\n吧。希望他能像这名字一般，弥天盖地\n击垮司马家。"]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[27]},{"op":"change_scene","args":[2,65535,65535,10,65535]},{"op":"actor_appear","args":[801,69,54,3,0]},{"op":"actor_appear","args":[570,54,54,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["良吏鲁芝"]},{"op":"place_name","args":["青州议事厅"]},{"op":"actor_action","args":[570,6]},{"op":"dialog","args":["&文官\n之前您下官查的事情，现在已经查到了。\n&文官\n当时跟著姜维被杀的妻子，据在场士兵说\n是个羌人。\n&鲁芝\n果然如此…那羌人女子就是这样，活得\n亮丽，死得也精彩。\n&文官\n另外，您也该知道朝廷最近回复五等爵制\n，您的爵位也派下来了。\n&鲁芝\n哦，是什么爵位？\n&文官\n您被封伯爵，是为阴平伯。\n&鲁芝\n阴平伯？哈哈哈哈哈…这是巧合还是\n故意呢？\n&文官\n您为什么要笑成这样？阴平伯很奇怪吗？\n&鲁芝\n你不知道阴平是什么地方吗？就是那个\n让一代名将姜伯约栽了的地方呀。\n&鲁芝\n（我们曾经有类似的经历，却因为诸葛亮\n的北伐而使我们有著完全不同的发展。）\n&鲁芝\n（曾经我想学你的壮烈，奋力反抗司马家\n，没想到最后还是卑躬屈膝去当人家部下\n，和努力到底的你相比，相差太远了。）\n&鲁芝\n（不过，我还是会用我自己的方法努力\n下去的。就算是一点点也好，也想多接近\n你一点。）"]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[117]},{"op":"change_scene","args":[2,65535,65535,64,65535]},{"op":"actor_appear","args":[96,64,54,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["司马昭故去"]},{"op":"place_name","args":["洛阳 晋王府"]},{"op":"dialog","args":["&司马昭\n炎儿，我交代的事情…你都记住了…\n&司马炎\n是的，我一定会照您的话去做。\n&司马昭\n很好…如果你胆敢违背其中一项，我一定\n会回来找你的…\n&司马炎\n不敢不敢，孩儿一定遵照父亲的指示。\n&司马昭\n炎儿，你知道为什么…为父会选择你…当\n世子…而不是…桃符？\n&司马昭\n我想过…桃符性情善良，和平稳健，名声\n也超过你。甚至因为他是大哥的儿子…所\n以让他当世子也…无妨…\n&司马昭\n但是当裴秀、何曾、贾充甚至平日拥戴\n桃符的山涛都为你说话的时候…为父终于\n知道你…才是适合…担任世子的人…\n&司马昭\n别以为为父不知道你在背后做的事情…\n&司马炎\n父王，我…\n&司马昭\n不，你拉拢人心的动作像极了宣王，\n光这点你就胜过桃符…\n&司马昭\n下去吧，我大晋的开国君王…顺便帮我把\n那个人也请进来。\n&司马炎\n是，父王。"]},{"op":"actor_move","args":[0,96,0,64,94,2]},{"op":"actor_select","args":[0,96,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"actor_appear","args":[24,64,94,0,0]},{"op":"actor_move","args":[0,24,0,64,54,0]},{"op":"actor_action","args":[24,0]},{"op":"dialog","args":["&曹绫\n没想到你会千里迢迢把我从邺城招来，\n不怕元姬生气？\n&司马昭\n元姬…和我患难这么多年…一定会相信\n我的…\n&司马昭\n今天我…是想和你做个交易…\n&司马昭\n现今曹氏宗族中，就你最有力量…希望你\n能约束住…所有忠于魏室的大臣或皇族，\n让炎儿接受禅让没有阻碍…\n&曹绫\n你准备拿什么和我交易？要我拱手让出\n兄长苦心经营的大魏，你也要有相当的\n觉悟。\n&司马昭\n皇族禁锢令…我已经交代炎儿…一定要在\n即位后解除…如此你们曹家人都可以重获\n自由…\n&司马昭\n不要担心炎儿会反悔…我们这些父祖辈的\n把肮脏事都做完了…他只会去扮演圣君…\n为了维护圣君形象，他不会反悔的…\n&曹绫\n我答应你，我也不想看到曹氏宗族和忠魏\n大臣血流成河。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&司马昭\n斗了这么多年，曹家和司马家的怨恨\n不知道能不能化解？\n&曹绫\n这种问题不应该问我，而是要看你们\n的作为…只是我们曹家可以做个例子，\n其身不正，虽令不从…\n&司马昭\n说得也是…其身不正，虽令不从…\n&司马昭\n（父亲、大哥，我们这样做正确吗？当\n我们有样学样的同时，后来是不是也会\n有人有样学样？）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,21,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["公元二六五年八月九日，晋王司马昭去世，世子司马炎继承王位。",1,0,1]},{"op":"caption","args":["十二月十三日，曹魏皇帝曹奂将皇位禅让给晋王司马炎，曹魏宣告灭亡。",1,1,1]},{"op":"caption","args":["自二二零年曹丕篡汉建立，二六五年被司马炎篡夺灭亡，立国共四十六年。",1,1,1]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[1,30,0,65535,65535]},{"op":"change_scene","args":[0,25,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["然司马昭的担忧仍然成真，一百多年后，司马家的天下被权臣刘裕篡夺。",0,0,1]},{"op":"caption","args":["出身寒微的刘裕为担心司马家的存在会威胁自己的皇位，屠杀了禅让的司马家。",1,1,1]},{"op":"caption","args":["自此亡国君王家族皆遭屠杀，被刘裕开了先例。",1,1,1]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[2,65535,65535,51,65535]},{"op":"actor_appear","args":[96,51,29,2,0]},{"op":"actor_appear","args":[3,51,45,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["故汉之将"]},{"op":"place_name","args":["洛阳 皇宫"]},{"op":"dialog","args":["&司马炎\n朕对于姜维的事情真的很好奇，听说你是\n当年姜维帐下的一员，想听听你的说法。"]},{"op":"actor_action","args":[3,6]},{"op":"dialog","args":["&柳隐\n老大的一生，只可用“忠缪”来形容。\n&柳隐\n忠于其国，缪于其身。不顾个人荣辱名声\n，把一切都奉献给国家，这就是老大。\n&柳隐\n他是最聪明却也是最愚笨的人…抱歉，\n陛下…若是继续说下去，微臣恐怕很难\n控制自己了…\n&司马炎\n朕已经大略明白姜维的为人了。虽是敌将\n，但是气节实在值得尊敬。\n&柳隐\n陛下，日后一定会有很多贬低老大的声音\n出现，臣只希望陛下能够明辨是非，知道\n哪些事情才是真的。\n&司马炎\n朕一定会牢记在心。\n&柳隐\n陛下，臣即将要返回蜀地，也请陛下\n多保重。\n&司马炎\n真可惜，朕认识你们这些蜀臣太晚了。\n才一见面就要分离，实在是感伤。"]},{"op":"dialog","args":["&柳隐\n（这样就好了，事情的真相就让我们这些\n幸存者继续传承下去，让世人知道老大\n真正的忠心表现。）"]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[2,65535,65535,68,65535]},{"op":"actor_appear","args":[713,48,64,1,0]},{"op":"actor_appear","args":[84,54,64,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["愚公移山"]},{"op":"place_name","args":["洛阳附近"]},{"op":"dialog","args":["&桓楷\n可恶！到最后还是没有办法阻止司马家\n篡位。大魏灭亡之后，更难为爹报仇了。\n&嵇凛\n仔细想想自己可以做的事情吧。可别再想\n逞什么匹夫之勇，上次被我救到算是你运\n气好。\n&桓楷\n我该怎么做？难道就这样眼睁睁看著\n司马家这样张狂下去？\n&嵇凛\n这一代办不到，下一代再做到就好了，\n这就是繁衍的深意。\n&桓楷\n下一代？"]},{"op":"dialog","args":["&嵇凛\n这样好了，我就帮我们子孙取名字，\n被取到名字的就继续桓家的使命。\n&嵇凛\n儿子就取作桓颢…孙子叫桓彝…曾孙嘛…\n&桓楷\n你居然想到我的曾孙去了！\n&嵇凛\n复仇大业持续个十几代都有可能…就叫做\n桓温吧！"]},{"op":"dialog","args":["&桓楷\n桓温……总觉得这名字好像有什么深意\n似的……\n&嵇凛\n没什么，只是听起来很威风而已。"]},{"op":"dialog","args":["&嵇凛\n（总不能告诉他是因为司马懿出身温县，\n我要他从司马家的根开始拔起。呵呵呵，\n要比狠毒，男人还不够格呢。）"]},{"op":"dialog","args":["&桓楷\n话说回来，这个名字怎么听都像个奸臣。\n&嵇凛\n会吗？我倒认为他会成为可以和孙权并肩\n的大英雄。"]},{"op":"dialog","args":["&桓楷\n等一下，你刚才好像说了我们的子孙……"]},{"op":"dialog","args":["&嵇凛\n糟、糟糕，说漏嘴了！"]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[2,65535,65535,33,65535]},{"op":"actor_appear","args":[3,30,60,1,0]},{"op":"actor_appear","args":[1,30,55,1,0]},{"op":"actor_appear","args":[27,30,50,1,0]},{"op":"actor_appear","args":[11,30,45,1,0]},{"op":"actor_appear","args":[18,35,60,1,0]},{"op":"actor_appear","args":[20,35,55,1,0]},{"op":"actor_appear","args":[16,35,50,1,0]},{"op":"actor_appear","args":[13,35,45,1,0]},{"op":"actor_appear","args":[21,40,60,1,0]},{"op":"actor_appear","args":[10,40,55,1,0]},{"op":"actor_appear","args":[8,40,50,1,0]},{"op":"if","cond":"test_flags","args":[[],[907]],"end":672},{"op":"actor_appear","args":[22,40,45,1,0]},{"op":"endif","args":[]},{"op":"actor_appear","args":[7,53,57,3,0]},{"op":"actor_appear","args":[24,53,52,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["最后的相聚"]},{"op":"place_name","args":["广元 姜维墓"]},{"op":"dialog","args":["&夏侯霸\n我特地带了个人来祭拜伯约。\n&赵统\n车骑将军，原来你平安无事？\n&夏侯霸\n命硬就是我最大的本钱，一时之间还\n死不了的。\n&曹绫\n小女子曹绫，前来拜谒故蜀大将军姜维\n的坟墓。\n&马岱\n等一下，你不是贼营的公主？\n&刘敏\n还贼营呢，现在都已经改朝换代了，这位\n公主和我们一样受到亡国之痛。\n&柳隐\n我们常败军的成员应该大部分都到这里了\n，只有像是廖化或是宗预这些已经去世的\n无法到这里来。\n&柳隐\n（小句，你现在在哪里呢？果然你还没有\n放弃…）\n&来忠\n虽然无法公开表示对大将军的怀念，但是\n我们不约而同选在这里集合。\n&向充\n（老师究竟到哪里去了？为什么今天这样\n重要的集会却看不到他的身影？）\n&罗宪\n虽说我现在是大晋的官员，但是心还是\n属于大汉，所以就算冒著生命危险也要\n帮大将军修筑好坟墓。\n&霍弋\n我和休然都是一样，虽然接受大晋的任命\n，但实际上还是以汉臣自居。\n&柳隐\n可以不要把我和你相提并论吗？你摆明就\n领俸禄领得很开心，还狂吃空缺，浮报预\n算。\n&霍弋\n我这是破坏大晋的经济嘛。\n&关索\n只可惜我只能待在南中，不能找南中女人\n以外的换换口味。\n&花鬘\n关索…你似乎对我很不满的啦…"]},{"op":"if","cond":"test_flags","args":[[],[907]],"end":681},{"op":"dialog","args":["&张嶷\n哈哈哈，都结了婚还想要偷腥，真不愧是\n关索呀。"]},{"op":"endif","args":[]},{"op":"dialog","args":["&曹绫\n诸葛果，你还好吧…\n&诸葛果\n我现在人在成都西山修行，每天都在为\n主公和杨姊姊祈福。\n&诸葛果\n杨姊姊生前无法和主公在一起，至少这个\n衣冠冢是将两人合葬的。\n&曹绫\n合葬的衣冠冢？那她可真是名符其实的\n姜夫人了。你羡慕她吗？\n&诸葛果\n我们活著的人也有另外的使命，那就是\n把主公和大汉的精神传承下去，果是这样\n认为的。\n&曹绫\n同感，活著的人都有活著的使命，至少也\n要让后来的人知道我们的奋斗才行。"]},{"op":"delay","args":[10]},{"op":"dialog","args":["&曹绫\n永别了，姜维…"]},{"op":"actor_face","args":[1,0,3]},{"op":"actor_face","args":[27,0,3]},{"op":"actor_face","args":[3,0,3]},{"op":"actor_face","args":[11,0,3]},{"op":"actor_face","args":[10,0,3]},{"op":"actor_face","args":[8,0,3]},{"op":"actor_face","args":[21,0,3]},{"op":"actor_face","args":[13,0,3]},{"op":"actor_face","args":[18,0,3]},{"op":"actor_face","args":[20,0,3]},{"op":"actor_face","args":[16,0,3]},{"op":"actor_face","args":[22,0,3]},{"op":"delay","args":[10]},{"op":"fade_in","args":[]},{"op":"change_scene","args":[1,16,65535,65535,65535]},{"op":"fade_out","args":[]},{"op":"caption","args":["姜维竭尽全力的复国计画失败，蜀和魏两国相继灭亡，",1,0,1]},{"op":"caption","args":["司马炎建立了晋政权，正式统治这两国旧有领地。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["司马懿父子经历十余年努力 终于夺取魏蜀两国，并顺利称帝，",0,0,1]},{"op":"caption","args":["但这并不代表第三代的司马炎无事可做。",1,1,1]},{"op":"delay","args":[5]},{"op":"caption","args":["晋朝内外仍有许多反抗司马氏的力量正在酝酿，",0,0,1]},{"op":"caption","args":["其中最强、最迅速的挑战便是晋武帝的宿敌孙皓。两人的战斗，才正要开始...",1,1,1]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[255]},{"op":"endif","args":[]},{"op":"play_sound","args":[0]},{"op":"change_scene","args":[2,65535,65535,62,65535]},{"op":"actor_appear","args":[258,39,70,3,10]},{"op":"actor_appear","args":[259,75,60,2,10]},{"op":"actor_appear","args":[260,63,76,1,10]},{"op":"actor_appear","args":[0,53,79,2,0]},{"op":"actor_appear","args":[3,48,84,0,0]},{"op":"actor_appear","args":[4,53,84,0,0]},{"op":"actor_appear","args":[14,58,84,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["真正的终局"]},{"op":"place_name","args":["雒阳皇宫"]},{"op":"delay","args":[3]},{"op":"dialog","args":["&姜维\n搜救的情况如何？"]},{"op":"actor_action","args":[14,6]},{"op":"dialog","args":["&马隆\n我们搜索了附近，只看见一对小孩的尸体\n，看起来应该是司马衷夫妇。\n&姜维\n可怜的一对小夫妻，本来以为司马家回归\n河内之后不会再产生牺牲者，结果没想到\n还是事与愿违。\n&姜维\n即刻通知司马家的人，并且准备厚葬\n他们。\n&马隆\n（不知道该怎么说，总觉得那对小夫妇\n就算长大也不会幸福。）\n&马隆\n老师，钟会就在皇宫里面，我们是不是\n要冲进去解决他？\n&姜维\n钟会确实是这次动乱的元凶，只要让他\n伏法，这次乱事就会结束了。\n&姜维\n不过，我不打算亲自去见钟会，这件事情\n就交给你们了。\n&柳隐\n这点我不懂了，平常老大你都会和敌人\n主将见面，怎么这次却不这么做？是因为\n钟会那家伙不值得尊敬？\n&姜维\n这或许是原因，但也不是主要原因。\n&姜维\n钟会虽然狡诈多智，靠著一个人就能掀起\n这么大规模的乱事。但他终究只是野心的\n集合体而已。\n&姜维\n一但野心破灭，他就再也没有威胁，\n也就不需要我去亲自对付他。"]},{"op":"actor_face","args":[0,0,1]},{"op":"dialog","args":["&句扶\n大将你要去哪里？\n&姜维\n去解决大汉未来真正的威胁…"]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[50]},{"op":"change_scene","args":[2,65535,65535,51,65535]},{"op":"actor_appear","args":[107,51,44,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["野心的尽头"]},{"op":"place_name","args":["雒阳皇宫"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[107,0]},{"op":"dialog","args":["&钟会\n我真的不懂，明明到这个龙椅不到数步\n的距离，却怎么样也跨不过去。\n&钟会\n我更是不懂，为什么这些人会傻傻地为\n拯救这个腐朽的政权出兵。\n&钟会\n彷彿这发生的一切都在和我作对一样。"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[848,51,96,0,0]},{"op":"actor_move","args":[0,848,0,51,53,0]},{"op":"actor_action","args":[848,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[107,0,2]},{"op":"dialog","args":["&钟会\n你是什么人？\n&女子1\n奉命来送你去见一个人。\n&钟会\n你是…\n&女子1\n马幼常虽然认为一切都在他计画内，但是\n你掀起的波澜实在太大了。\n&女子1\n他没有想到你可以煽动这么多人跟著你\n造反，你太过危险了。\n&钟会\n那家伙，如果不让他自以为一切都在\n掌握之中，又怎么会上钩？\n&女子1\n同样地你也是。\n&钟会\n到最后变成我们两个人在互婊吗？\n&女子1\n不，因为他相信，就算你有本事搞得\n天翻地覆，姜维也能够收拾。因为他\n是个不能用常识来解释的男人。"]},{"op":"actor_action","args":[107,0]},{"op":"dialog","args":["&钟会\n不，那是他走运，绝对不是他的本事！\n&女子1\n仔细想想，他当初看似莽撞的救援襄阳，\n结果让现在司马家愿意出兵。\n&女子1\n他在那拚死救援建业，结果不知不觉收拢\n东吴军民的心。\n&女子1\n这些你可以用运气好来解释？"]},{"op":"actor_action","args":[107,0]},{"op":"dialog","args":["&钟会\n姜维这个人究竟多谋还是少谋，我真的\n搞不懂了。\n&女子1\n你没有必要搞懂，因为你马上就要死了。"]},{"op":"actor_face","args":[107,0,0]},{"op":"dialog","args":["&钟会\n哈哈哈，我钟会背负著恶名而死，也是\n不错的结果。\n&钟会\n纵不能流芳百世，也要遗臭万年！\n至少我能在历史上留名。"]},{"op":"delay","args":[5]},{"op":"actor_move","args":[0,107,0,51,29,2]},{"op":"actor_action","args":[107,17]},{"op":"dialog","args":["&钟会\n这个位子曹叡坐过、司马炎坐过，刘禅\n也坐过。\n&钟会\n我比他们都强，当然有资格坐这个位子。\n&钟会\n娘，您看清楚了吗？孩儿现在是皇帝了，\n没有人可以再欺负您，您要不要看现在\n的孩儿一眼？"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[3]},{"op":"change_scene","args":[2,65535,65535,41,65535]},{"op":"actor_appear","args":[49,58,56,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["君臣的终点"]},{"op":"place_name","args":["雒阳金镛城"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[0,58,32,2,0]},{"op":"wait_frame","args":[]},{"op":"actor_move","args":[0,0,0,58,48,2]},{"op":"actor_action","args":[0,0]},{"op":"dialog","args":["&刘禅\n哦，朕的英雄，大汉的救世主呀！"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n陛下，姜维救驾来迟，还请恕罪。\n&刘禅\n爱卿何罪之有，你扫平了叛逆，拯救了\n大汉，朕要重重给你封赏。\n&刘禅\n说吧，你想要什么官位呢？当大司马？\n丞相？还是晋位公爵？"]},{"op":"actor_action","args":[0,0]},{"op":"dialog","args":["&姜维\n陛下，这些都不重要。\n&刘禅\n你想要称王？还是受领九锡？这些也都\n可以商量。\n&姜维\n臣也不想要这些。\n&刘禅\n那就怪了，你真的什么都不想要？\n&姜维\n如果真要说的话，臣只希望陛下同意\n一件事情。\n&刘禅\n哈哈哈，不用说一件事了，就算是一百件\n事，朕都答应你。\n&姜维\n那么臣就说了。"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n希望陛下即刻退位，将皇位让给皇子。\n&刘禅\n什么？你说什么？\n&姜维\n臣希望陛下即刻退位。\n&刘禅\n你知道你在说什么吗？身为臣下可以这样\n逼迫主上？\n&姜维\n就算是逼迫也好，臣也希望陛下能够遵守\n自己的诺言。\n&刘禅\n你这作为和司马师、孙綝有什么两样？\n你根本是准备篡位吧。"]},{"op":"actor_action","args":[0,0]},{"op":"dialog","args":["&姜维\n不，臣对皇位一点兴趣都没有，只是认为\n这是对陛下最好的决定。\n&刘禅\n叫朕退位是最好的决定？\n&姜维\n陛下，这次的大祸究竟是谁导致的，\n您应该心知肚明。\n&姜维\n钟会和马谡虽有才智，但陛下过度重用，\n委以军国重任，使两人自以为神机妙算，\n功高盖世，而策动谋反。\n&姜维\n如果陛下恩威并施，以法度规范，就不致\n酿成叛乱之心了。\n&姜维\n陛下引进外族、任用奸臣导致这样的灾祸\n，不管怎么看都是难辞其咎。\n&刘禅\n朕是受害者，你有什么证据说这些是朕\n的主意？\n&姜维\n臣握有许多陛下亲手署名的诏书，您该\n明白是谁拿给臣的。\n&姜维\n现在陛下退位，还可以保有好名声，\n若是这些诏书流出去，陛下到时只怕\n连名声都保不住了。\n&刘禅\n难道不能商量吗？朕让你称王，让你成为\n辅国大臣，一切权力和你共享…\n&姜维\n您还不明白吗？这些完全不重要。\n臣只要您退位。\n&姜维\n为了让陛下能够心服，臣也作出一个\n重大决定。"]},{"op":"delay","args":[3]},{"op":"actor_appear","args":[40,58,32,2,0]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&诸葛瞻\n姜维，这一切到底是怎么回事？\n&姜维\n思远，姜维无能，在援救陛下过程中被\n叛军残兵所杀。\n&诸葛瞻\n咦？\n&姜维\n之后的大将军和大将军府就交给你了。\n&刘禅\n你到底想要做什么？\n&姜维\n臣征战这么多年，也累了倦了，现在想要\n做自己想做的事。\n&姜维\n就让臣陪陛下一起走下历史的舞台吧。"]},{"op":"delay","args":[3]},{"op":"fade_in","args":[]},{"op":"play_sound","args":[13]},{"op":"change_scene","args":[2,65535,65535,29,65535]},{"op":"actor_appear","args":[60,52,38,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["败者塑造的历史"]},{"op":"place_name","args":["雒阳"]},{"op":"actor_appear","args":[40,52,98,0,0]},{"op":"actor_move","args":[0,40,0,52,47,0]},{"op":"actor_action","args":[40,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[60,0,2]},{"op":"dialog","args":["&刘谌\n卫将军，你能回答我吗？为什么人们会\n这么愚蠢，宁愿毁掉好不容易到手的和平\n也要自相残杀成这样？\n&刘谌\n本来我以为灭晋平吴之后，天下就再也\n没有战争。没想到不但事与愿违，而且\n居然还多死了这么多人。\n&诸葛瞻\n那是因为，人们都想成为胜利者，想要\n一手掌控一切，所以才会发生这种事。\n&刘谌\n这场战争有胜利者？兄弟们全死了，\n雒阳被打成废墟，整个中原几乎是一片\n浩劫。\n&诸葛瞻\n您说得没错，这场战争完全没有胜利者，\n大家全都是败者。\n&诸葛瞻\n钟会和马谡全都死在这场乱事，包括文鸯\n在内的所有反叛军将领也都已经战死。\n&诸葛瞻\n外族将领也死伤惨重，各部族元气大伤，\n就算能逃回去也很难再重整势力了。\n&诸葛瞻\n您的父皇因为这次乱事而感到心灰意冷，\n已经决定把皇位传给您了。\n&刘谌\n什么？！为什么会这样？难道是因为皇兄\n死亡的缘故？\n&诸葛瞻\n事情的真相您不需要细想，只要知道\n陛下的退位是既成事实就好。"]},{"op":"actor_action","args":[60,2]},{"op":"dialog","args":["&刘谌\n是姜维对吧！是他逼父皇退位的吧！\n搞个半天，真正的胜利者是他。\n&诸葛瞻\n您错了，不是说过没有胜利者了吗？\n姜维早在之前就被反叛军残兵所害，\n已经死了。"]},{"op":"actor_action","args":[60,0]},{"op":"dialog","args":["&刘谌\n什么？！怎么会这样…"]},{"op":"actor_action","args":[40,6]},{"op":"dialog","args":["&诸葛瞻\n这场战争大家都是败者，就算是活著的\n我们也都是败者。\n&诸葛瞻\n但是这也是转机，因为回顾过去的历史，\n还没有像现在这样是由败者来塑造的。\n&诸葛瞻\n不知道您愿意和在下一起继续塑造这个\n历史吗？\n&刘谌\n这个担子真的好沉重…"]},{"op":"fade_in","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":121},{"op":"play_sound","args":[69]},{"op":"change_scene","args":[2,65535,65535,51,65535]},{"op":"actor_appear","args":[60,51,29,2,0]},{"op":"actor_appear","args":[112,49,47,0,0]},{"op":"actor_appear","args":[178,55,47,0,0]},{"op":"actor_appear","args":[40,41,47,1,0]},{"op":"actor_appear","args":[199,41,52,1,0]},{"op":"actor_appear","args":[102,41,57,1,0]},{"op":"actor_appear","args":[720,41,62,1,0]},{"op":"actor_appear","args":[47,65,47,3,0]},{"op":"actor_appear","args":[670,65,52,3,0]},{"op":"actor_appear","args":[45,65,62,3,0]},{"op":"actor_appear","args":[652,65,67,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["新朝人事"]},{"op":"place_name","args":["雒阳宫殿"]},{"op":"actor_action","args":[178,6]},{"op":"actor_action","args":[112,6]},{"op":"dialog","args":["&陈泰\n魏国丞相陈泰。\n&陆凯\n吴国丞相陆凯，特来恭贺新帝登基。\n&刘谌\n两位免礼，朕年纪还轻，须要各位的\n扶持，今后还请多多照顾。\n&陈泰\n陛下客气了，魏国仍为大汉藩属，行臣下\n之礼乃是应该。\n&刘谌\n不，这次若无魏、吴以及大家的帮忙，\n大汉恐怕无法度过这次的危机。\n&刘谌\n今后朕会视你们为兄弟之邦，而非从属\n之国，还请你们多多支持。\n&陆凯\n有陛下的这句话就够了，吴国今后一定会\n全力支持大汉，直到千秋万世。"]},{"op":"actor_action","args":[178,0]},{"op":"actor_action","args":[112,0]},{"op":"dialog","args":["&刘谌\n经过这次的动乱，全肇因于钟会和马谡\n这两位奸臣。\n&刘谌\n然而朕必须要承认，太上皇虽然没有过错\n，在这过程中完全受制于人。但皇帝集中\n权力于中央的祸患还是不容忽视。\n&任恺\n（没有过错吗？说得还真好听。）\n&郤正\n（幸好陛下知道及时退位，让众人可以\n为他擦脂抹粉，要不然追究起来，皇室\n的威信可以说完全扫地。）\n&刘谌\n因此，朕决定重新任命诸葛瞻为大司马，\n并且将所有的政务和军权都交给他。"]},{"op":"actor_face","args":[102,6,0]},{"op":"dialog","args":["&荀顗\n陛下，把所有的权力都交给大司马，那么\n您怎么办呢？\n&刘谌\n谁说皇帝不能没有权力的？过去太上皇\n不也和丞相相安无事？\n&刘谌\n至于说是不是会出现下一个司马家？\n朕不敢断言，但是现在地方上有许多\n屏障，情况应该和当时差很多。"]},{"op":"actor_face","args":[40,6,0]},{"op":"dialog","args":["&诸葛瞻\n臣愿接受这个任命，为了陛下和大汉，\n臣将鞠躬尽瘁，死而后已。\n&刘谌\n大司马，这个天下并非朕或是刘家的天下\n，而是大家的天下。\n&刘谌\n所以我们名为主从，实为同僚，这点还请\n你记著。\n&诸葛瞻\n是的，臣一定会牢记在心。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":138},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,68,65535]},{"op":"actor_appear","args":[60,42,62,0,0]},{"op":"actor_appear","args":[40,48,62,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["众人的智慧"]},{"op":"place_name","args":["雒阳附近"]},{"op":"dialog","args":["&刘谌\n到现在我还一直在想，这样做对不对呢？"]},{"op":"actor_face","args":[40,6,3]},{"op":"dialog","args":["&诸葛瞻\n陛下，请您注意对自己的称呼。"]},{"op":"actor_face","args":[60,0,1]},{"op":"dialog","args":["&刘谌\n现在只有我们两人，实在不需要拘泥太多\n礼数。\n&刘谌\n更何况我早就说过，现在我们是共同奋斗\n的伙伴，而非君臣关系。"]},{"op":"actor_action","args":[40,0]},{"op":"dialog","args":["&诸葛瞻\n其实不瞒陛下说，这一连串的动乱几乎\n让我不知所措。\n&诸葛瞻\n在动乱前，还有伟大的英雄可以依靠，\n但在动乱之后，连这最后的依靠都没了。\n&刘谌\n他也没有留给我们答案，只是要我们自己\n去摸索该怎么做。\n&诸葛瞻\n或许这也表示英雄的时代已经过去，\n接下来是平凡人的时代吧。\n&刘谌\n没错，我很平凡，所以需要大家的扶持\n才能撑起这个国家。\n&诸葛瞻\n我更是平凡，在这之前，没有人引导根本\n就无法独立思考。\n&刘谌\n哈哈哈，我现在终于明白大将军的意思。\n&诸葛瞻\n哦，陛下请说。\n&刘谌\n他想要的天下，应该就是现在这个样子。\n一个由平凡人互相扶持依赖才能继续\n走下去的天下。\n&诸葛瞻\n嗯，这么说来，过去大家一直想要依赖\n英雄，结果众人变得懒得思考，而一股脑\n将权力和责任丢给他。\n&诸葛瞻\n英雄尝到权力的滋味后害怕失去一切\n，于是开始压迫众人。众人因而怨恨，\n将攻击的矛头指向英雄。\n&诸葛瞻\n于是，英雄胜利则继续压迫众人，众人\n胜利则杀害英雄，然后继续怠惰，并且\n等待新的英雄。\n&诸葛瞻\n这样的循环从来没有停止过，而双方也就\n一直持续著受害。\n&刘谌\n或许现在就是终结一切的时候，虽然前途\n茫茫，但总是个崭新的开始。\n&诸葛瞻\n是呀…"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,33,65535]},{"op":"actor_appear","args":[129,33,55,3,0]},{"op":"actor_appear","args":[220,38,59,3,0]},{"op":"actor_appear","args":[18,38,52,3,0]},{"op":"fade_out","args":[]},{"op":"delay","args":[5]},{"op":"title_text","args":["文鸯的真意"]},{"op":"place_name","args":["文鸯之墓"]},{"op":"dialog","args":["&文虎\n没想到居然还有人肯来为二哥祭拜。\n&赵统\n我虽然讨厌他，但认为他比起那个周旨\n要正常多了。\n&赵统\n而且事后回想起来，如果不是因为他，\n恐怕我还是沉浸在安乐的环境底下。\n&甘宁\n以为人来说，没有人比他更烂。但是以\n武艺来说，他还是天下无双。\n&甘宁\n我能够打败他，只是因为他根本无心和我\n对决，否则胜负还在未定之天。"]},{"op":"actor_face","args":[129,0,1]},{"op":"dialog","args":["&文虎\n二哥很清楚，他的价值在太平之时就会\n完全消失，所以他打算用自己的生命\n来建立真正的太平之世。\n&文虎\n邓艾在临死前见过二哥，跟他说出了自己\n的计画。\n&文虎\n邓艾认为皇帝的权力过大是祸乱的根源，\n而姜维的做法根本无法有效削减皇帝的\n权力。\n&文虎\n除了制衡的力量外，他认为最直接的办法\n，就是让储君消失，让皇统摇摇欲坠。\n&赵统\n这么说来，他杀太子并不只是为了让陛下\n和大将军敌对，还有这个目的？\n&文虎\n是的。皇权失去亲族的力量，会被迫去\n依赖外人，甚至到最后虚位化。\n&文虎\n邓艾和姜维两人虽然在做法上不同，\n但是目标却是一致的。\n&甘宁\n不过你遗漏了一件事。\n&文虎\n什么事？\n&甘宁\n你没想过文鸯为什么会这么听邓艾的话？\n&文虎\n说起来，我也不是很懂。\n&甘宁\n因为文鸯一直把邓艾看做是自己当年没能\n守护的父亲。\n&文虎\n原来如此呀…"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&赵统\n接下来你打算怎么办？\n&文虎\n我受到二哥的托付，有延续文家香火的\n义务。\n&文虎\n接下来大概只会找个地方隐居，好好度过\n剩下的人生吧。\n&赵统\n说得也是呀，你现在还是被通缉的身份，\n恐怕要等到赦令下来才能随便走动吧。\n&文虎\n那么你们呢？\n&赵统\n我会继承父亲和弟弟的遗志，继续守护\n著大汉。\n&甘宁\n我有该回去的地方…"]},{"op":"actor_face","args":[18,0,2]},{"op":"dialog","args":["&赵统\n（说得也是呀，那个诸葛尚似乎让这女人\n有了可以回去的地方。）"]},{"op":"fade_in","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":176},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,34,65535]},{"op":"actor_appear","args":[41,57,47,2,0]},{"op":"actor_appear","args":[707,57,53,0,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["谯郡附近"]},{"op":"dialog","args":["&糜照\n阿尚呀，我还真佩服你的度量。\n&诸葛尚\n你在说什么？\n&糜照\n自己的老婆居然跑去祭拜别的男人，要是\n我早就抓狂了。\n&诸葛尚\n毕竟是战场上曾经以命相搏的对手，\n就像我之前也去祭拜过邓忠，这完全\n没什么呀。\n&糜照\n你终究是太年轻了，不懂男女之情的\n精妙和危险之处。\n&诸葛尚\n算了吧，“龙骑士”阿照居然还敢对我\n说教？"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&糜照\n不过说真的，你有没有一点后悔？\n&诸葛尚\n后悔什么？\n&糜照\n娶妻终究是要取名门闺秀呀，像甘宁这种\n不是出身名门的就当个妾就好了。\n&诸葛尚\n你在说什么呀！"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[220,7,58,1,0]},{"op":"actor_move","args":[0,220,0,57,58,0]},{"op":"actor_action","args":[220,0]},{"op":"dialog","args":["&糜照\n不如这样好了，我带你去多认识一些真正\n的名门闺秀，到时把她们娶进来再扶正。\n&诸葛尚\n阿照…别说了…\n&糜照\n所谓老婆就是要带得出门，报上家名\n也不会觉得蒙羞才是好。\n&糜照\n光看脸可爱有什么用，老了还不是会变丑\n，以后你一定会后悔的。\n&诸葛尚\n阿照，我觉得你现在一定会后悔说\n这些话。\n&甘宁\n糜照，你想要死一次试试看吗？"]},{"op":"actor_face","args":[707,0,2]},{"op":"dialog","args":["&糜照\n哇靠，什么时候出现在我背后的。\n&诸葛尚\n听我说，我不会听阿照的话去找别的\n女人。\n&甘宁\n其实你也不用担心，要开后宫我也没有\n意见。\n&甘宁\n我是心胸宽大但没什么耐心的人，如果\n拈花惹草还可以，动真心就不行。\n听清楚了吗？\n&诸葛尚\n是。"]},{"op":"dialog","args":["&诸葛尚\n（话虽然是这么说的，但我很清楚，\n要是真的开后宫，一定会死无葬身之\n地……）"]},{"op":"dialog","args":["&甘宁\n很好。那么糜照呢？\n&糜照\n关我什么事？\n&甘宁\n有种再说一遍？\n&糜照\n我知道了…"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":193},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,71,65535]},{"op":"actor_appear","args":[14,52,47,2,0]},{"op":"actor_appear","args":[4,49,52,0,0]},{"op":"actor_appear","args":[3,54,52,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["各自的未来"]},{"op":"place_name","args":["雒阳附近"]},{"op":"actor_action","args":[14,6]},{"op":"dialog","args":["&马隆\n两位将军真的不改变主意吗？\n&柳隐\n我都年纪一把了，现在不退还准备\n惹人嫌吗？\n&句扶\n我是常败军的元老，当大将他不在的时候\n，常败军也没有必要继续存续。\n&柳隐\n今后是你们年轻人的时代，要好好干呀。\n&马隆\n那是当然，这样才不至于愧对老师当日\n的托付。"]},{"op":"actor_action","args":[14,0]},{"op":"dialog","args":["&句扶\n虽说现在暂时将所有看得到的威胁排除，\n大汉应该不需要再作战。\n&句扶\n但万一真的有这一天的时候，也请你一定\n要撑住。\n&马隆\n现在吴魏已经没有威胁，外族也元气大伤\n。剩下要做的，大概也就是扫讨那些叛乱\n的残兵而已。\n&马隆\n不过这些还不是当务之急，毕竟回复叛乱\n造成的创伤比较重要。\n&柳隐\n看来你脑袋还挺清楚的，这样我们就能\n放心引退了。"]},{"op":"actor_action","args":[14,6]},{"op":"dialog","args":["&马隆\n两位征战多年，现在好不容易等到了这\n难能可贵的和平，还请两位多多保重，\n多享受点安稳的时光。\n&柳隐\n那是当然，我的曾孙还等著我回家抱呢。\n&句扶\n（大哥，再请稍等一下。我马上就来接你\n回去汉昌了。）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":216},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,46,65535]},{"op":"actor_appear","args":[8,36,47,2,0]},{"op":"actor_appear","args":[10,36,55,0,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["雒阳大司马府"]},{"op":"dialog","args":["&向充\n真倒楣，大将军府的成员引退了大半，\n到最后我却得和你共事。\n&来忠\n不爽不要做。\n&向充\n你说得倒轻松，我把工作这样一丢，\n还对得起老师的托付？\n&来忠\n既然这样就少抱怨一点。要知道，现在\n大司马府里面纯正出自大汉的人已经\n不多了。\n&来忠\n特别是那三个从晋灭亡后加入的人更是\n优秀到让人害怕。\n&向充\n喂，别动什么歪脑筋，那些人虽然可能\n让我们显得很无能，但对他们的存在对\n大汉可是好事。\n&来忠\n呵呵呵，开玩笑的，我可不像爹那样\n老是没有安全感。\n&向充\n你刚说的可一点也不像是开玩笑。"]},{"op":"actor_appear","args":[111,46,5,2,0]},{"op":"actor_appear","args":[549,51,5,2,0]},{"op":"actor_appear","args":[721,56,11,2,0]},{"op":"actor_move","args":[0,111,0,46,46,2]},{"op":"actor_move","args":[0,549,0,51,46,2]},{"op":"actor_move","args":[0,721,0,56,46,2]},{"op":"actor_face","args":[111,0,3]},{"op":"actor_face","args":[549,0,3]},{"op":"actor_face","args":[721,0,3]},{"op":"dialog","args":["&杜预\n你们刚才说什么吗？\n&张华\n好像提到我们三人的样子。\n&魏舒\n说来听听吧。"]},{"op":"actor_face","args":[8,0,1]},{"op":"actor_face","args":[10,0,1]},{"op":"dialog","args":["&来忠\n哈哈哈，你们误会了。\n&向充\n对对对，今后大家都是同僚，要好好\n相处呀。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":243},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,69,65535]},{"op":"actor_appear","args":[9,51,57,1,0]},{"op":"actor_appear","args":[570,57,52,3,0]},{"op":"actor_appear","args":[564,57,57,3,0]},{"op":"actor_appear","args":[565,57,62,3,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["汝南袁家"]},{"op":"dialog","args":["&文官\n我父亲是袁胤，在袁公路灭亡之后短暂\n投奔刘勋，但不久后就被孙策俘虏。\n&文官\n父亲不肯屈从孙氏，所以并没有任官，\n直到我这一代才隐姓埋名在吴郡当个\n小吏。\n&文官\n这是家族族谱，请过目。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&女子\n我的父亲是袁耀，也就是袁公路的太子。\n&女子\n在袁公路败亡之后投奔刘勋，后被孙策\n俘虏。接著就在孙氏政权任官。\n&女子\n父亲只有我这个女儿，为了家族在东吴\n的地位，他将我嫁给孙奋成为侧室。\n&女子\n十多年前，孙奋因卷进诸葛恪事件，加上\n滥杀手下官吏，被孙峻流放。\n&女子\n之后我们一直住在离建业很远的章安，\n没想到却能因此逃过去年的兵灾。\n&袁綝\n嗯…这段时间真是辛苦你了。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&男子\n我的父亲是袁熙，在幽州兵败之后大家\n就各自逃散。\n&男子\n为了怕被曹家人追杀，所以我们一直隐姓\n埋名躲著。\n&袁綝\n没想到二哥也还有后代留下来…看来袁家\n剩下来的后代比我想像得要多不少。"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[9,6]},{"op":"dialog","args":["&袁綝\n在下这次到处广招袁家人，就是希望汝南\n袁家能够再次复兴。\n&袁綝\n虽说经历过数次屠杀的灾祸，但只要有\n我们这些后代在，要复兴绝非梦想。\n&男子\n那是当然，我们都愿意遵奉叔父您来\n当家，现在您可是大汉的高官之一。\n&袁綝\n可惜在下不管怎么苦修，学问和涵养都\n还是无法配得上四氏三公的袁家。\n&袁綝\n要是我们族人有人能够以学问出仕，在下\n是很愿意将当家之位让出。\n&文官\n这点不用担心，就算我们这一代不行，\n过个几代应该就能恢复了。\n&女子\n到时也希望世人能够重新正面评价祖父\n和伯祖那些人，不要再被曹家或孙家的\n记载诱导了。"]},{"op":"actor_action","args":[9,0]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[799,63,21,2,0]},{"op":"actor_move","args":[0,799,0,63,57,3]},{"op":"actor_action","args":[799,0]},{"op":"dialog","args":["&李明\n你还记得我吗？\n&袁綝\n不会吧…到现在都还活著，你到底\n几岁了呀。\n&李明\n曾祖母都活到九十以上，我这个年纪\n又有什么好意外的？\n&袁綝\n你也看起来太年轻了吧…对了，现在不是\n管这个的时候，义父和义母他们应该…\n&李明\n不在人世了。不过如果你想要听他们\n之后过得怎么样的话，我倒是很乐意\n分享。"]},{"op":"actor_action","args":[9,6]},{"op":"dialog","args":["&袁綝\n请一定要告知在下。\n&李明\n呵呵呵，说话的口气和用语都变了，看来\n你是真心想要复兴袁家呀…"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":268},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,50,65535]},{"op":"actor_appear","args":[55,49,58,1,0]},{"op":"actor_appear","args":[21,55,58,3,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["成都宫殿"]},{"op":"actor_action","args":[21,6]},{"op":"dialog","args":["&罗宪\n老师，久未相见，学生特来相您请安。\n&谯周\n令则呀，确实是好久不见了。\n&罗宪\n您的脸色憔悴，气色看起来很不好，\n可以告诉学生发生了什么事？\n&谯周\n唉，你也知道我毕生追求的梦想，就是\n一个在地人可以当家自主的益州。\n&谯周\n前些日子太子在此地，我花了很大的力气\n让太子渐渐明白使用在地人的重要性。\n&谯周\n没想到文鸯一杀害太子，全部心血都\n白费了。\n&谯周\n听说新的总督要来益州，只怕又重演过去\n“荆楚人贵”的历史。\n&罗宪\n老师您别担心，学生这次前来正是因为\n担任新任都督的副手，而那位都督您绝对\n认识。\n&谯周\n哦？"]},{"op":"actor_appear","args":[15,51,7,2,0]},{"op":"actor_move","args":[0,15,0,51,50,2]},{"op":"actor_action","args":[15,6]},{"op":"actor_face","args":[21,0,0]},{"op":"actor_face","args":[55,0,0]},{"op":"dialog","args":["&张翼\n允南，久违了。\n&罗宪\n老师，张将军正是我们新任的益州都督。\n&谯周\n这还真想不到呀…"]},{"op":"actor_action","args":[15,0]},{"op":"dialog","args":["&张翼\n别看他诸葛思远那样，经过这些年的历练\n之后，他也逐渐展现出大人物的风范。\n&张翼\n更何况他自认才能远逊于丞相，所以相当\n讲究和其他人的合作。\n&谯周\n这么说来，朝廷的旨意是允许我们自治？\n&张翼\n这也算是答谢我们益州人这么多年来的\n牺牲奉献吧。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&谯周\n唉，多年来我一直认为益州人不该积极\n协力大汉参加战争，现在看来似乎是错\n了。\n&张翼\n允南的见解也不是没有道理，我虽然侥幸\n靠著军功爬到现在的位子，但相对地也让\n许多益州子弟战死沙场。\n&张翼\n现在的我，也是踏著他们的尸体爬上来\n的。正因如此，我必须要好好治理这块\n土地，才能对得起他们的牺牲。"]},{"op":"actor_action","args":[55,6]},{"op":"dialog","args":["&谯周\n伯恭，这次谯周一定尽全力帮你的忙。"]},{"op":"actor_action","args":[21,6]},{"op":"dialog","args":["&罗宪\n也请别忘记在下，身为谯老师的学生，\n一定不会让师门蒙羞的。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":281},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,28,65535]},{"op":"actor_appear","args":[17,46,45,0,0]},{"op":"actor_appear","args":[12,46,51,0,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["关羽墓"]},{"op":"actor_action","args":[17,6]},{"op":"dialog","args":["&廖化\n关将军，现在江陵已经收复，大汉也已经\n完成了兴复大业，您可以真的安息了。\n&廖化\n廖淳虽然不才，但是有幸参与到这光荣的\n作战过程，特来向您报告。\n&宗预\n仔细想想，元俭你好像比关家的子孙都\n还要尊敬关将军嘛。"]},{"op":"actor_face","args":[17,0,2]},{"op":"dialog","args":["&廖化\n那是因为现存的关家子弟没有人亲身和\n关将军共事过，就算是关索，也几乎没有\n和关将军相处多久。\n&廖化\n不过这样也好，留在过去的老人只需要\n我一个人就够了。\n&宗预\n哈哈哈，这才是我认识的元俭。\n&宗预\n过去的你被关将军牵绊得太深了，以至于\n为了弥补他的遗恨变得太过偏执。\n&廖化\n或许吧，为了爬到和关将军相近的位子，\n我把所有竞争者都当作敌人，也不思考\n对方是不是也和我一样爱大汉。\n&廖化\n现在回想起来，真的感到很羞愧呀。\n&宗预\n现在再后悔也没什么用，毕竟你身为车骑\n将军，大汉安危是你责无旁贷的使命。\n&廖化\n思远他终究还是年轻，要他这样的年轻人\n担负起整个国家，只怕他负荷不了。\n&宗预\n所以这才是上天要留下我们这些老人的\n用途。\n&宗预\n或许我们不见得可以活几年，但至少可以\n用这几年来减轻年轻人的负担。\n&廖化\n你说得是。走吧，我们好久没有一起\n谈心了。\n&宗预\n元俭，两个老男人谈心你认为很浪漫？"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":303},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,72,65535]},{"op":"actor_appear","args":[16,51,51,2,0]},{"op":"actor_appear","args":[11,46,58,0,0]},{"op":"actor_appear","args":[13,51,58,0,0]},{"op":"actor_appear","args":[22,56,58,0,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["南中"]},{"op":"dialog","args":["&关索\n想不到你们都和我一样，选择跑到南中\n来任职。\n&霍弋\n我这边霍氏企业生意做这么大，哪可能\n丢下来呢？\n&霍弋\n谅那个马隆再聪明，也没想到我虽然破产\n，但在交州又另外闯出一片天。\n&关索\n我劝你下次别再睹这么大了。\n&刘敏\n反正在雒阳的诸葛思远和蒋家两个小辈\n也不会喜欢听我啰嗦，就索性跑来南中\n这边养老了。\n&刘敏\n虽说临走前，那个小小斌一直哭著不让我\n走，我可是非常为难，当下还在决定是要\n走还是不要走…\n&关索\n拜托，我们也不喜欢听你啰嗦。\n&张嶷\n关将军，倒是你为什么还是要回到这来？\n其实你在雒阳可以有更好的发展。\n&关索\n这个嘛，毕竟我跟这块土地有难以分割\n的感情。\n&关索\n再说，如果没有我，谁来和现在新任的\n孟家豪酋沟通？\n&张嶷\n是呀，没有人会想到孟琰做出这样的决定\n，一直对大汉忠心耿耿的他，最后居然\n会选择背叛大汉。\n&关索\n不，孟琰他就是忠心耿耿才会参加这场\n乱事。\n&关索\n想想这些年来，大汉在这里的统治都是\n很薄弱，只是靠著南中豪酋来压制反对\n势力。\n&关索\n前一阵子的交州作战，我们驱使了大量\n的南中人前往异地作战，他们会不满是\n可以预见的。\n&张嶷\n没错，孟琰强迫压抑那些南中人，到最后\n不但自己会被吞灭，南中也还是会大乱。\n&张嶷\n不如选择参加乱事，一口气消灭掉那些\n不安定的因子。\n&关索\n是的，这样看来，我觉得丞相身边的亲信\n，不管出身哪里，到最后都变得很像呀。\n&张嶷\n嗯，不管是孟琰、马谡或是姜维吗？"]},{"op":"actor_appear","args":[20,51,5,2,0]},{"op":"actor_move","args":[0,20,0,51,44,2]},{"op":"actor_action","args":[20,2]},{"op":"actor_face","args":[16,0,0]},{"op":"dialog","args":["&花鬘\n关索，你为什么又跑了？这是你第几次\n逃婚的啦。\n&关索\n有话慢慢说，我怎么会逃婚呢？只是和\n这些兄弟们问好而已。\n&霍弋\n是呀，我们到时一定来喝喜酒。\n&刘敏\n我保证一定会来致词。"]},{"op":"actor_action","args":[20,0]},{"op":"dialog","args":["&花鬘\n拜托，就只有这个不要的啦。\n&张嶷\n请放心，这次关索不会逃跑了，因为他说\n他无法眼睁睁看著孟姑娘一个人处理这些\n南中事务。\n&花鬘\n哦？\n&关索\n毕竟我没有忘记孟琰的托付。"]},{"op":"actor_face","args":[20,0,0]},{"op":"dialog","args":["&花鬘\n从明天开始，我就是孟家的一族之长，\n你可不能再用这样的态度对我说话。\n&关索\n那是当然的。"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":318},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,41,65535]},{"op":"actor_appear","args":[49,64,53,3,0]},{"op":"actor_appear","args":[213,56,53,1,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["雒阳太上皇寝宫"]},{"op":"dialog","args":["&张皇后\n陛下您还在不痛快吗，想想您也连续抱怨\n超过半年了。\n&刘禅\n朕到现在都搞不懂他在想什么，把朕搞掉\n自己却什么都不要，对他有什么好处？\n&张皇后\n想要梓童说一下自己的看法？\n&刘禅\n咦？你刚才自称什么？\n&张皇后\n陛下到现在才发现，似乎也有点迟钝了。\n&张皇后\n姜维会这样做，除了他自己的政治意图外\n，对陛下也确实是好事。\n&张皇后\n想想您退位之后，再也没有人质疑您过去\n为什么任用钟会和马谡，仍被歌颂为中兴\n之主，如此不好吗？\n&刘禅\n但是朕还是想要…\n&张皇后\n陛下想要变成真正的孤家寡人？以前您\n还有陈祗与黄皓帮忙，现在还有谁？\n&张皇后\n更何况黄皓怎么死的，陛下应该也很清楚\n，您认为自己还能再相信别人？"]},{"op":"actor_face","args":[49,0,1]},{"op":"dialog","args":["&刘禅\n其实朕非常不喜欢你刚才说的那些话，\n但也不能否定这些话的正确性。\n&刘禅\n你说得没错，朕或许真的已经不适任国君\n，若是继续霸著那个位子，可能到最后\n只会变成像孙权那样的昏君。\n&张皇后\n陛下一直都是明白人，只是身边的人都\n看扁您了。"]},{"op":"actor_face","args":[49,0,3]},{"op":"dialog","args":["&刘禅\n这样好吗？跟朕一起待在这无聊的寝宫\n太浪费人生了，你真心爱的人应该是…\n&张皇后\n陛下，梓童既然都如此自称了，为什么\n您还要拒绝？难道只有姊姊才是您的\n皇后？\n&刘禅\n不是这样的…\n&张皇后\n这样就好，梓童以前是大汉的皇后，现在\n是大汉的皇太后，还请陛下明白这点。\n&张皇后\n（关索，我们毕竟也不是小孩了，彼此都\n有应尽的责任。过去事情就让它过去吧）"]},{"op":"delay","args":[5]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":346},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,35,65535]},{"op":"actor_appear","args":[662,59,70,0,0]},{"op":"actor_appear","args":[565,53,70,0,0]},{"op":"actor_appear","args":[44,58,46,2,0]},{"op":"actor_appear","args":[140,53,46,2,0]},{"op":"actor_appear","args":[206,56,52,2,0]},{"op":"actor_appear","args":[713,20,41,1,0]},{"op":"actor_appear","args":[84,17,46,1,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["港口"]},{"op":"actor_action","args":[206,6]},{"op":"dialog","args":["&张特\n请女王您放心，有我张特在，管他狗奴国\n有多少人，通通不是问题。\n&台与\n还请您多多费心。\n&张特\n不用担心啦，我这刘玄德第二的外号\n可不是叫假的。\n&关彝\n（怎么办，真的觉得好丢人。）\n&张遵\n（但是跟著大哥好像真的不会错，就暂且\n相信他吧。）\n&关彝\n（谁不知道你眼睛在看哪里？你明明就\n迷上邪马台国的侍女团。真搞不懂，\n那些叫秋叶四十八的女人有这么迷人？）\n&张遵\n（不懂就闭嘴，人家秋叶四十八可不是\n一般的团体，而是从一般人中挑选出来，\n让观众跟著她们一起成长…）\n&关彝\n（杀了我吧…）"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[565,0,1]},{"op":"dialog","args":["&女子\n女王，这些人真的可靠吗？"]},{"op":"actor_face","args":[662,0,3]},{"op":"dialog","args":["&台与\n张将军曾经是毌丘俭的手下，应该是没有\n问题。\n&张特\n现在我就答谢各位，准备来高歌一曲。\n&台与\n应该吧…\n&女子\n要是这些人再这样胡闹下去，我可不可以\n把他们丢下海呢？\n&台与\n由纪临，为什么你每次都可以满脸笑容\n说出这么可怕的话？腹黑属性？\n&女子\n呵呵呵…"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&嵇凛\n怎么？可爱的女王离开了，感觉很寂寞？\n&桓楷\n不是这样的。只是觉得我们派出的援军\n真的能够达成任务？\n&嵇凛\n别小看张特将军，他虽然看起来很不正经\n，但是指挥能力和智略都是顶级的。\n&桓楷\n原来如此…接下来你有什么打算？天下\n回复和平，魏国的政务上了轨道，司马家\n现在也回归平淡，似乎已经失去目标了。\n&嵇凛\n你的人生还真贫乏呀，难道除了对司马家\n报仇以外就什么都没有了？\n&桓楷\n我真的想不到还能做什么了…"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&嵇凛\n入赘当嵇家的女婿如何？\n&桓楷\n咦？\n&嵇凛\n还听不明白吗？\n&桓楷\n这…不行…\n&嵇凛\n为什么？难道你觉得我不够好？\n&桓楷\n不，我们桓家五世帝师，怎么可以入赘\n呢？\n&嵇凛\n真是小器的男人，我们嵇家也不差呀，\n至少也是当代名士的代表。\n&桓楷\n不，名士哪比得上名门！"]},{"op":"dialog","args":["&嵇凛\n那好吧，这件事就这么算了……\n&桓楷\n喂，不要啊……\n&嵇凛\n呵呵呵……"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&女子\n女王，很羡慕她们是吗？\n&台与\n我是邪马台国的女王，再怎么样都得尽到\n自己的职责。\n&台与\n只是…\n&女子\n只是？\n&台与\n还是有这么一点点的羡慕…"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":359},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,70,65535]},{"op":"actor_appear","args":[79,58,30,2,9]},{"op":"fade_out","args":[]},{"op":"place_name","args":["龟山监狱"]},{"op":"dialog","args":["&马扁\n八月中秋山林凉，风吹大地草枝摆。\n甘宁老母赶羚羊，市场羊毛超级卖。\n赶羚羊呀草枝摆，草枝摆呀赶羚羊。\n&马扁\n庭院织芭为君开，督兰山晓金桔摆。\n老迹埋呀金桔摆，金桔摆呀老迹埋。\n&马扁\n呜呜呜，阿扁真够衰，跟著起兵不成，\n还被关进自己盖的监狱。\n&马扁\n天啊，阿扁错了吗？阿扁错了吗？"]},{"op":"actor_appear","args":[718,96,60,3,0]},{"op":"actor_move","args":[0,718,0,69,60,0]},{"op":"actor_action","args":[718,0]},{"op":"dialog","args":["&丘本\n关死你这贪赃枉法混蛋，你也该想到\n自己有今天了吧。\n&马扁\n暗阴阳勒，你这死秃子，阿扁跟你有什么\n深仇大恨？\n&丘本\n只要是贪官污吏，就是丘某的敌人。\n&马扁\n关你屁事呀！\n&丘本\n本来是不管我的事啦，不过现在你被关，\n就准备被我管啦。\n&丘本\n我是新任廷尉。\n&马扁\n该死的，要就一刀宰了阿扁，干嘛一口气\n判阿扁十几年，要关死阿扁喔。\n&丘本\n你美呀，这只是你的“笼谈购地案”而已\n，你“国务机要费案”和“二次金改案”\n都还没宣判呢。\n&马扁\n政治迫害呀，阿扁无罪呀！\n&丘本\n去你的无罪，问问江东人，哪个不知道\n你马扁手握“海角七亿”。\n&马扁\n呜呜呜，阿扁身体不舒服，想要申请\n戒护就医。\n&丘本\n你这家伙花样怎么这么多？\n&马扁\n你有点人性好不好，阿扁这几天拉肚子，\n万一像先帝那样挂掉怎么办？\n&丘本\n………"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":375},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,0,65535]},{"op":"actor_appear","args":[727,53,43,3,0]},{"op":"actor_appear","args":[564,58,43,3,0]},{"op":"actor_appear","args":[573,45,43,1,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["谧友堂"]},{"op":"dialog","args":["&皇甫谧\n嗯，恢复得不错，看来你是差不多\n痊愈了。\n&旅人\n真是多谢神医，若没有您，恐怕我早就\n死掉了。\n&皇甫谧\n不，最重要是你有著想要活下去的念头。\n只要有这念头，再麻烦的病都有治愈的\n可能。\n&皇甫谧\n你先回去吧，接下来只要按时服这处方上\n的药就可以了。\n&旅人\n多谢大夫。"]},{"op":"actor_move","args":[0,573,0,45,92,2]},{"op":"actor_select","args":[0,573,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"actor_face","args":[727,0,1]},{"op":"dialog","args":["&皇甫谧\n左大夫，准备看下一个病患吧。\n&男子\n皇甫大夫，我到现在都一直在想，身为\n大夫的我们是不是能多做些什么？\n&男子\n光事在这里开堂行医，能够救到的人\n终究是太有限了。\n&皇甫谧\n不用著急，现在我们就这样慢慢一步步来\n，先求回复到过去华大夫在世时的荣景。\n&男子\n您是说组成那支传说中的“医龙”团队？\n&皇甫谧\n嗯，那只是第一步而已。\n&皇甫谧\n目前我还在思考新药的开发，最近从发霉\n的桃子上发现了一种东西，给了我不少\n的灵感呢。\n&男子\n哦？\n&皇甫谧\n这要从生病的原因开始说起，或许我们\n一开始想的方向就错了。左大夫，你有\n兴趣听下去吗？\n&男子\n那当然，能跟著大夫您行医，是我左分利\n此生最大的荣耀。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":398},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,61,65535]},{"op":"actor_appear","args":[647,57,59,2,0]},{"op":"actor_appear","args":[232,54,66,0,0]},{"op":"actor_appear","args":[585,61,66,0,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["著作郎府"]},{"op":"actor_action","args":[647,6]},{"op":"dialog","args":["&陈寿\n其实在下邀请各位前来也没有别的目的，\n只是想要和大家讨论一下。\n&陈寿\n在下虽然奉命写史，但还是想要多知道\n一下遗漏的史料，毕竟魏吴两地的资料\n并不容易收集。"]},{"op":"actor_action","args":[647,0]},{"op":"dialog","args":["&韦昭\n早就知道了，你看过《吴书》有什么\n感想？\n&王沈\n在下的《魏书》已经被看过了？\n可以给个机会让在下改改？"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&陈寿\n说老实话，在下真的认为王处道的\n《魏书》有很多问题。\n&陈寿\n别的不说，为什么连高贵乡公的事件都\n略掉不提？\n&王沈\n拜托，在下当时被司马家控制住了，要\n在下怎么写？"]},{"op":"actor_face","args":[585,0,3]},{"op":"dialog","args":["&韦昭\n真丢脸，董狐之笔没听过吗？真是丢了\n史学者的脸。"]},{"op":"actor_face","args":[232,0,1]},{"op":"dialog","args":["&王沈\n既然敢这么说，在下也不客气了。\n&王沈\n《吴书》还不是错漏百出？你就没有过\n度美化孙家父子？孙坚一个流氓被你写\n成英雄，残杀无辜还说成替天行道。\n&王沈\n呵呵，更别说孙策当年怎么对袁术卑躬\n屈膝，然后主子大难临头就背弃他。\n&韦昭\n你的《魏书》就没有鬼扯？曹操明明就\n对袁绍低声下气，还说成一直都反抗他。\n&韦昭\n还有曹操跟袁绍借兵五千的事情到哪\n去了？\n&陈寿\n咳，两位可否停止互相攻讦？"]},{"op":"actor_face","args":[232,0,0]},{"op":"actor_face","args":[585,0,0]},{"op":"dialog","args":["&王沈\n这么说来，《季汉书》其实也有不少问题。\n&韦昭\n同意，对关羽的描述太过正面了，他对\n我们来说只是个粗暴的武人。\n&陈寿\n等一下，这点请恕在下不能认同，荆州\n的事情难道孙权和吕蒙就没有责任？\n&王沈\n这点在下倒是同意，孙权野心之大，就算\n不是关羽守荆州也迟早会被他偷袭。\n&陈寿\n看来还有得战了，在下就去叫人买鸡排。\n&韦昭\n我的那份不要切。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[800],[]],"end":421},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,33,65535]},{"op":"actor_appear","args":[561,31,55,3,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["傅佥墓"]},{"op":"actor_appear","args":[32,96,55,3,0]},{"op":"actor_move","args":[0,32,0,37,55,3]},{"op":"actor_action","args":[32,0]},{"op":"dialog","args":["&蒋舒\n傅佥，我来看你了。"]},{"op":"actor_face","args":[561,0,1]},{"op":"dialog","args":["&男童\n叔叔是谁呀？\n&蒋舒\n叔叔才想问小朋友是傅佥的什么人。\n&男童\n我叫做傅著，他是我爹，当年镇守阳安关\n虽然壮烈牺牲，但却保全了大汉。\n&男童\n娘跟我说，他是个了不起的大英雄。\n&蒋舒\n没错，他真的是个大英雄。\n&蒋舒\n不过你知道你爹是怎么死的？\n&男童\n嗯…好像是一个叫做蒋舒的人害死的。\n&蒋舒\n很好。那么如果蒋舒出现在你面前，\n你会怎么做呢？"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[565,96,55,3,0]},{"op":"actor_move","args":[0,565,0,43,55,3]},{"op":"actor_action","args":[565,0]},{"op":"dialog","args":["&女子\n够了。\n&男童\n娘！"]},{"op":"actor_face","args":[32,0,1]},{"op":"dialog","args":["&蒋舒\n原来是嫂子，这样或许更好…\n&蒋舒\n我苟活在这世上其实一点意义也没有，\n倒不如让傅佥的家属来报仇。\n&蒋舒\n是我害死傅佥的，我羡慕他的成就，嫉妒\n他的勇敢，所以在魏军来到时，我选择\n杀害这位曾经帮过我无数次的好兄弟。\n&女子\n听好，我确实恨你恨到巴不得杀你。\n&女子\n但是，如果真的杀了你，就只会让这仇恨\n的种子继续发展下去。\n&蒋舒\n你不用担心，我的家人早就认为我死了，\n没有人会找你们报仇的。\n&蒋舒\n快点吧，你们应该是对我怀抱著满腔的\n愤怒，如果现在不报复，还等待何时？\n&男童\n娘曾经听爹说过，愤怒产生仇恨，仇恨\n带来苦难。\n&男童\n所以我们不应该放任自己的愤怒宣泄\n，是不是这样呢？\n&女子\n听到了吗？我们虽然恨你，但是不希望\n这个仇恨将我们引入黑暗面。\n&女子\n既然上次的动乱你没有死，或许上天是\n有旨意要你活著做些有意义的事。\n&女子\n回想起傅佥临死前对你说的话吧，我不\n认为他是对你怀抱著怨恨而死。\n&蒋舒\n（你是我的兄弟呀…傅佥，我现在终于\n明白，你的那句话并不是矫情呀。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&蒋舒\n呜呜呜…啊啊啊…"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":448},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,25,65535]},{"op":"actor_appear","args":[99,62,55,2,0]},{"op":"actor_appear","args":[98,70,60,3,0]},{"op":"actor_appear","args":[117,70,65,3,0]},{"op":"actor_appear","args":[663,70,70,3,0]},{"op":"actor_appear","args":[706,57,60,1,0]},{"op":"actor_appear","args":[97,57,65,1,0]},{"op":"actor_appear","args":[110,61,62,0,0]},{"op":"actor_appear","args":[136,66,62,0,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["河内司马家"]},{"op":"dialog","args":["&羊祜\n我们是来向司马家的各位辞行的。\n&王浑\n接下来我们要去荆州上任，未来恐怕\n很难再来见各位。\n&王元姬\n这样也好，总不能故晋旧臣都一直往河内\n跑，现在已经不是司马家的天下了。\n&王元姬\n更何况之前参加叛乱的几乎都是故晋旧臣\n，我们可不希望大家再卷进麻烦了。\n&司马孚\n看看我们司马家夺权的代价，从二哥这代\n一直到他的曾孙，几乎每代都有人横死。\n&司马孚\n最可怜就是那个司马衷，他才不过七岁\n左右，就被钟会玩弄后杀害，实在是太\n不幸了。"]},{"op":"actor_action","args":[110,0]},{"op":"actor_action","args":[136,0]},{"op":"dialog","args":["&司马攸\n所以我才决定要参加这次平乱，让司马家\n摆脱混乱制造者的印象，日后才有机会\n过平淡的日子。"]},{"op":"actor_face","args":[110,0,3]},{"op":"actor_face","args":[136,0,3]},{"op":"dialog","args":["&羊祜\n您说得虽是，但日后司马家真的能够完全\n摆脱政治吗？\n&王元姬\n不知道，但是大家会尽力去做，否则\n悲剧只会再次发生而已。"]},{"op":"actor_action","args":[97,6]},{"op":"dialog","args":["&司马攸\n今后大家将各奔东西，请勿再以司马家\n为念。\n&司马攸\n你们要效忠的对象应该是大汉，司马家\n往后将只是一个普通的河内名门而已。"]},{"op":"actor_action","args":[110,6]},{"op":"actor_action","args":[136,6]},{"op":"dialog","args":["&王浑\n是，我们明白。\n&羊祜\n但也请您记得，还是有人以曾经身为大晋\n的臣子感到骄傲的。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":474},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,21,65535]},{"op":"actor_appear","args":[169,48,67,0,0]},{"op":"actor_appear","args":[184,61,59,3,0]},{"op":"actor_appear","args":[175,61,54,3,0]},{"op":"actor_appear","args":[185,61,49,3,0]},{"op":"actor_appear","args":[109,36,54,1,0]},{"op":"actor_appear","args":[584,36,49,1,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["吴军营帐"]},{"op":"dialog","args":["&施绩\n建业皇宫的修建情况如何？"]},{"op":"actor_face","args":[175,6,2]},{"op":"dialog","args":["&吾彦\n目前进度超前了两成，或许两个月后就能\n回去建业。\n&施绩\n很好，这段日子真是辛苦大家了，不但让\n各位负担这么沉重的重建工作，还要出兵\n支援雒阳。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[584,0,2]},{"op":"dialog","args":["&陶璜\n这样好吗？现在北朝力量明显衰弱，若是\n我们趁机复国，他们应该没有办法出兵\n南下。\n&施绩\n世英，你也看见这次战争的浩劫，从北\n到南，几乎无处不受害，难道你也像\n钟会或文鸯那样，是期盼战争的疯子？\n&陶璜\n哈哈哈，别扣我这么大的帽子，只是\n开玩笑而已，能在上次战役中捡到一条\n小命，偷笑都来不及了。\n&施绩\n（这家伙说话根本就不像在开玩笑。）"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&周处\n………\n&薛莹\n子隐，你在想什么？从刚才就一直在\n发呆。\n&周处\n我只是在想齐万年那家伙死前说的话。\n&周处\n过去我们虽然一直说打山越是为了大吴\n的长治久安，，但心底其实是不是在\n享受残杀山越的乐趣？\n&薛莹\n那家伙的话别就太认真看待，谁都知道\n齐万年是个可恨的蛮族。\n&周处\n真的只是这样吗？\n&施绩\n族群的问题可没有这么容易解决，我也\n同意子隐的看法，或许我们只是在压抑\n自己的兽性而已。\n&施绩\n不过至少现在我们已经开始反思自己的\n行为，比起过去应该是有很大的进步。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[184,6,2]},{"op":"dialog","args":["&鲁淑\n正是如此，现在衰弱的大吴，光是江东人\n和江北人合作还不足以支撑。\n&鲁淑\n若是能够和山越和解，对我大吴的复兴\n应该会有很大的帮助。"]},{"op":"actor_action","args":[169,0]},{"op":"dialog","args":["&施绩\n嗯，目前吴王还年轻，日后许多事情都要\n大家的扶助，吴国的将来就拜托各位了。\n&陶璜\n（真是悲惨呀，我们的戏分到这里就\n完了，不知道以后会不会有人做我们的\n故事？）\n&陶璜\n（开玩笑的。一个暴君和色鬼对峙十六年\n的无聊故事有谁会想看？）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[]],"end":502},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,51,65535]},{"op":"actor_appear","args":[68,51,29,2,0]},{"op":"actor_appear","args":[7,51,47,0,0]},{"op":"actor_appear","args":[669,41,47,1,0]},{"op":"actor_appear","args":[665,41,52,1,0]},{"op":"actor_appear","args":[86,41,62,1,0]},{"op":"actor_appear","args":[801,41,57,1,0]},{"op":"actor_appear","args":[112,65,47,3,0]},{"op":"actor_appear","args":[83,65,52,3,0]},{"op":"actor_appear","args":[88,65,57,3,0]},{"op":"actor_appear","args":[73,65,62,3,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["邺城宫殿"]},{"op":"actor_action","args":[7,6]},{"op":"dialog","args":["&夏侯霸\n雒阳那边的事情都已经处理完了，现在\n夏侯霸正式回归魏国。\n&曹芳\n嗯，我等夏侯将军已经很久了，只要你\n回归，魏国的人事就差不多可以底定了。\n&夏侯霸\n陛下，夏侯霸岂是如此重要之人？\n&夏侯和\n二哥，我们夏侯家一直是大魏的中流砥柱\n，更何况魏国的复兴您也出力甚多，就\n抬头挺胸接受魏王的赞赏吧。\n&夏侯霸\n多谢魏王的抬爱，今后夏侯霸将会为您\n效力，粉身碎骨，在所不辞。"]},{"op":"actor_action","args":[7,0]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹芳\n在座的各位几乎都经历过大魏的昌盛期，\n大家至少都从明皇帝时期就仕官，甚至\n还有见过武皇帝的。\n&何曾\n（那不就是老夫吗？哈哈，国有一老，\n如有一宝嘛。）\n&曹芳\n只是希望大家明白一点，现在的魏国和\n大魏还是有差。虽然声威大不如前，但\n却是最适合存续的型态。\n&曹芳\n相对于以前的大起大落，还是保持低调\n存续比较重要。\n&曹芳\n因此，我们只需要保国安民，切勿再思考\n恢复大魏荣光，否则只会像这次叛乱那样\n，除了制造伤亡外一无所得。"]},{"op":"actor_face","args":[83,6,0]},{"op":"dialog","args":["&费曜\n但是防人之心不可无呀，之前雒阳那边\n不就恐吓过我们？日后直接派兵来袭也\n不是不会发生。"]},{"op":"actor_face","args":[801,6,0]},{"op":"dialog","args":["&鲁芝\n这点请魏王不用担心，首先是朝廷方面\n已经改朝换代，现任皇帝威信不足，需要\n我们的支持。\n&鲁芝\n此外主政的诸葛瞻也是可以信赖的人物，\n只要他主政，我们魏国不会有问题。"]},{"op":"actor_face","args":[86,6,0]},{"op":"dialog","args":["&张虎\n魏王也请别忘了我，光靠著之前在河内和\n寿春建立的功绩，就足以让野心家忌惮\n三分。\n&张虎\n我们不要主动攻打别人，但也要让别人\n知道攻打我们所需要付出的代价。\n&曹芳\n确实呀，有这位张辽之后在，魏国也有著\n足以吓阻别人的武力。\n&曹芳\n只是可以的话，我还是希望这样的小康\n局面能够永远维持下去。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[923]],"end":519},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,73,65535]},{"op":"play_music","args":[208,0]},{"op":"actor_appear","args":[27,42,52,0,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["渭水"]},{"op":"dialog","args":["&马岱\n庞会，请原谅我必须用这种方法来阻止\n你。\n&马岱\n你的执念太强了，强到已经让我没办法\n有其他的选择。"]},{"op":"actor_appear","args":[2,94,52,3,0]},{"op":"actor_move","args":[0,2,0,52,52,3]},{"op":"actor_action","args":[2,0]},{"op":"dialog","args":["&杨兰\n我可记得，当年有个人的执念一点也\n不输庞会。"]},{"op":"actor_face","args":[27,0,1]},{"op":"dialog","args":["&马岱\n果然是你呀…\n&杨兰\n我不认为庞会那家伙会责怪你，相对地\n，他心中似乎还期盼你去阻止他。\n&杨兰\n他也知道自己的执念是罪恶，但那却是\n他生存的根本。\n&杨兰\n如果自杀，他没办法向他老爹交代，\n所以他期望你杀了他，这样他才好\n放下这一切。\n&马岱\n他真的是太可悲了…\n&杨兰\n先别说庞会了，你对于自己的未来有什么\n打算？\n&马岱\n大概找个地方隐居吧，毕竟就如同之前\n说过的，我也负有传承马家的责任。\n&杨兰\n既然如此，你有没有兴趣陪我做一件\n事？\n&马岱\n什么事？\n&杨兰\n造反。\n&马岱\n咦？"]},{"op":"play_music","args":[208,255]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[923]],"end":532},{"op":"play_sound","args":[20]},{"op":"change_scene","args":[2,65535,65535,20,65535]},{"op":"actor_appear","args":[673,74,55,3,0]},{"op":"actor_appear","args":[557,62,55,1,0]},{"op":"fade_out","args":[]},{"op":"place_name","args":["五部匈奴营帐"]},{"op":"actor_action","args":[557,6]},{"op":"dialog","args":["&刘渊\n父王，这次没有达成使命，孩儿真的\n很惭愧。\n&刘豹\n看来你还真是染上了汉人的习惯，我们\n匈奴人可没有这么重视荣誉，只要人活著\n就好。\n&刘豹\n看看这次参加起事的领袖，能够活著回来\n的只有你一个，还不感到幸运？\n&刘渊\n这点孩儿完全不懂，明明汉军当时强势\n无比，绝对足够将孩儿赶尽杀绝，为何\n他们没有那样做？"]},{"op":"actor_action","args":[557,0]},{"op":"dialog","args":["&刘豹\n你终究是年纪太小了，就算智慧过人，\n很多大人的事情你还是看不透。\n&刘豹\n看看你的行为举止和生活习惯，和在雒阳\n的汉人有什么两样？\n&刘豹\n要是杀了你，日后那些汉人岂不错失利用\n你来控制匈奴的机会？\n&刘渊\n他们是希望孩儿成为下一个金日磾？\n&刘豹\n没错，反正这样对我们大匈奴现在也\n没有坏处。\n&刘豹\n主力部队都在雒阳一战失去，现在的我们\n哪有和汉人一战的能力？不如暂且归附，\n换得生存空间。\n&刘渊\n原来如此，那么孩儿愿意充当和雒阳往来\n的使者。\n&刘豹\n为了大匈奴的存续，日后你可辛苦了。\n&刘豹\n想想我们能有机会和汉人谈和，也算是\n幸运了。\n&刘豹\n那些失去领袖的羌人、鲜卑人只会被汉人\n像杀狗一样屠戮殆尽…\n&刘渊\n他们也太可怜了，其实那些人不过是信了\n钟会的花言巧语，为自己族群争取权益\n而已…难道真的没办法拯救他们？\n&刘豹\n方法还是有，除非有个人能够统整他们\n的力量，结成同盟来抵抗汉人…"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[920,923]],"end":565},{"op":"play_sound","args":[107]},{"op":"if","cond":"comment","args":["R形象"],"end":536},{"op":"endif","args":[]},{"op":"if","cond":"comment","args":["R形象"],"end":538},{"op":"endif","args":[]},{"op":"if","cond":"comment","args":["R形象"],"end":540},{"op":"endif","args":[]},{"op":"change_scene","args":[2,65535,65535,20,65535]},{"op":"actor_appear","args":[27,62,45,2,0]},{"op":"actor_appear","args":[604,62,66,0,0]},{"op":"actor_appear","args":[470,57,66,0,0]},{"op":"actor_appear","args":[592,52,66,0,0]},{"op":"actor_appear","args":[482,47,66,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["新盟主"]},{"op":"place_name","args":["仇池外族营帐"]},{"op":"dialog","args":["&羯族兵1\n盟主为什么还是没来？汉人的讨伐军都\n已经到阵前了。\n&西羌兵1\n这次讨伐军统帅是马隆，据说是个厉害\n角色，该怎么办？\n&马岱\n怕什么？难道过去盟主拯救你们的事情\n是假的？\n&鲜卑兵1\n但这次汉军来势汹汹，我们真的敌得\n过吗？\n&马岱\n真可悲呀，要是姚柯回或是秃发树机能\n还在，你们还会说这样的话？"]},{"op":"actor_appear","args":[2,20,55,1,0]},{"op":"wait_frame","args":[]},{"op":"actor_face","args":[27,0,3]},{"op":"actor_face","args":[604,0,3]},{"op":"actor_face","args":[470,0,3]},{"op":"actor_face","args":[592,0,3]},{"op":"actor_face","args":[482,0,3]},{"op":"dialog","args":["&杨兰\n真是丢人呀，才不过来个马隆就让你们\n吓成这样，我过去可是打过诸葛亮的。\n&马岱\n（虽然打输…）"]},{"op":"actor_action","args":[2,2]},{"op":"dialog","args":["&杨兰\n敌人兵力虽然多，但是经过长途跋涉，\n在体力和士气上都不如我们。\n&杨兰\n而那个马隆也不过就我在姜维阵营时的\n小弟，还帮我提过枪，有什么好怕？\n&杨兰\n现在大家只有通力合作，才有一线生机。\n否则到时候被打败，汉人绝对不留活口。"]},{"op":"actor_action","args":[2,0]},{"op":"actor_action","args":[592,6]},{"op":"dialog","args":["&氐族兵1\n没错，我绝对支持盟主！\n&杨兰\n不错，你这氐族小子有骨气，叫什么\n名字？\n&氐族兵1\n我叫飞龙！\n&杨兰\n好，我收你当义子，你就改姓杨。\n&氐族兵1\n多谢盟主，杨飞龙这名字还真是响亮。\n&杨兰\n（呼，这些人虽然骁勇，但是脑袋还是\n挺单纯的。）\n&杨兰\n（我只是假装和汉人打仗，其实早就\n和马隆说好，让他们看到我们就退。）\n&杨兰\n（只有这样才能避免这些人被屠杀，\n而我也可以藉著当盟主来抑止这些人\n再度起兵的念头。）\n&杨兰\n（姜维呀，我为了你可是尽心尽力，\n你没有选我，其实我到现在还是有点\n生气。）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[921,923]],"end":584},{"op":"play_sound","args":[57]},{"op":"change_scene","args":[2,65535,65535,3,65535]},{"op":"actor_appear","args":[1,56,68,3,0]},{"op":"actor_appear","args":[40,45,68,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["影子参谋"]},{"op":"place_name","args":["雒阳大司马府"]},{"op":"dialog","args":["&诸葛果\n小瞻，这件事情就如此处理就好。\n不用担心，你的结论是正确的。"]},{"op":"actor_action","args":[40,6]},{"op":"dialog","args":["&诸葛瞻\n多谢姊姊。虽说我贵为大司马，但还是\n感觉很多事情无法掌握好。\n&诸葛果\n不用担心，如果有什么没办法解决的，\n尽管来找姊姊。"]},{"op":"actor_action","args":[40,0]},{"op":"dialog","args":["&诸葛瞻\n姊姊，其实我还是替您感到不值。\n&诸葛瞻\n明明一直跟在姜维身边，没想到最后他\n居然丢下您而去。\n&诸葛果\n那是因为我们主仆缘分已尽，请不要责怪\n主公。\n&诸葛瞻\n还是越想越生气，耽误了您的人生，\n到最后却溜得不见踪影。\n&诸葛瞻\n您不用担心，虽说现在要找可以匹配的\n对象有点难，但我一定会想办法的。\n&诸葛果\n不需要了，我想一直待在这里就好。\n&诸葛果\n等到事情告一段落，或许可以去成都附近\n学习道法。\n&诸葛瞻\n难道袁将军不行吗？他对姊姊您也是\n一往情深，家世好，到现在也未娶…\n&诸葛果\n袁将军应该有更合适的对象，例如说弘农\n杨家。\n&诸葛瞻\n真是的，为什么您总是这么固执呢？"]},{"op":"actor_appear","args":[42,30,59,1,0]},{"op":"wait_frame","args":[]},{"op":"actor_face","args":[40,0,3]},{"op":"dialog","args":["&黄崇\n大司马，打扰您姊弟相处时间真不好意思\n，但前线有要事相告。\n&黄崇\n马隆将军的讨伐军日前在仇池战败…而\n击败他的人是…\n&诸葛瞻\n杨兰。\n&黄崇\n咦？您怎么知道？\n&诸葛果\n那是我的主意，想要听听吗？"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[],[922,923]],"end":604},{"op":"play_sound","args":[56]},{"op":"change_scene","args":[2,65535,65535,28,65535]},{"op":"actor_appear","args":[24,53,45,0,0]},{"op":"actor_appear","args":[553,46,45,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["曹家的柱石"]},{"op":"place_name","args":["邺城郭太后墓"]},{"op":"dialog","args":["&曹绫\n嫂子她一辈子都是这么辛苦。\n&曹绫\n早年因为本郡叛乱而被迫收尽后宫，经历\n许多磨难后获得皇兄的宠幸，成为皇后。\n&曹绫\n但是没过多久皇兄就过世，嫂子变成太后\n却没有过一天好日子。\n&曹绫\n被司马家掌控不说，还得面对一次又一次\n曹家人死去的悲伤。\n&辛宪英\n至少在临终前还亲眼见到魏国复兴，曹家\n人能再度摆脱司马家的控制，她也算是\n苦尽甘来了。"]},{"op":"actor_face","args":[553,0,1]},{"op":"actor_face","args":[24,0,3]},{"op":"dialog","args":["&曹绫\n真是抱歉，要拉著你这个外人来探望\n嫂子。\n&辛宪英\n别这么说，自从搬来邺城之后，公主\n可是一直照顾著我，而且还帮忙琇儿\n在魏国找到新工作。\n&辛宪英\n回想起过去面对司马懿夺权却没有采取\n任何行动，真的感觉很惭愧。\n&曹绫\n你一个人背负著辛家和羊家的前途，自然\n要做最安全的决定，没什么好抱歉的。\n&曹绫\n更何况上次姜维得救还是依靠你，这个\n人情我也得还一下。\n&辛宪英\n嗯…还在惦记著姜维？"]},{"op":"actor_face","args":[24,0,1]},{"op":"dialog","args":["&曹绫\n这段时间我真的思考了很久，或许自己\n是真的对他有好感吧…\n&辛宪英\n这个样子还真像甄宓…"]},{"op":"actor_face","args":[24,0,3]},{"op":"dialog","args":["&曹绫\n说得也是，你过去也曾经和娘一起在\n邺城生活过。\n&辛宪英\n不只这样，她那迷糊天然的样子，让我\n还不自觉想要多照顾她呢。\n&辛宪英\n甄宓她虽然一直那样迷迷糊糊，但对自己\n感情却很认真，在没有得到结论以前会\n一直去钻牛角尖，就像您一样。\n&曹绫\n只可惜我就是一直这样思考而不行动，\n等到最后搞清楚时已经太迟了。\n&辛宪英\n没关系，缘分这种事情本来就不能\n太强求。\n&曹绫\n也对，我就把剩下的生命用在守护魏国\n上面好了。\n&辛宪英\n真不愧是公主，就算是失意也只难过一下\n，难怪当时就算是司马昭也打不倒您的\n意志。"]},{"op":"actor_face","args":[24,0,1]},{"op":"dialog","args":["&曹绫\n不，当时我真的输到山穷水尽，连求生的\n意志都输掉了，若不是他…\n&辛宪英\n还是别勉强自己，我们回去一起来骂\n那些薄情的男人好了。\n&辛宪英\n您知道吗？当初羊耽那个笨蛋有多不\n浪漫…"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[923],[]],"end":634},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,0,65535]},{"op":"actor_appear","args":[212,47,33,2,1]},{"op":"actor_appear","args":[0,47,42,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["回归平淡"]},{"op":"place_name","args":["冀城姜家"]},{"op":"dialog","args":["&姜母\n维儿，这样子真的好吗？丢下这一切\n躲到这地方来…"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n娘，真的很抱歉。本来孩儿是想要功成\n名就来孝敬您，没想到最后还是让您过\n苦日子。\n&姜母\n娘一点也不在乎这样的生活，而是维儿\n你的名声呀。\n&姜母\n明名平定这次动乱的是你，到最后居然\n变成是诸葛瞻，而你却被说成是无能的\n统帅。"]},{"op":"actor_action","args":[0,0]},{"op":"dialog","args":["&姜维\n真的没有关系，是我要思远这样对外\n宣布的。\n&姜维\n要是孩儿被描述成平乱英雄，那么思远\n他的威信就会减损，对于未来国家治理\n也不是什么好事。\n&姜母\n这样也好，如果维儿你看得开，其实做\n母亲的也没什么好说。\n&姜母\n对娘来说，只要在自己有生之年还看著\n孩子平安地活著就好。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜母\n只是…你真的不考虑续弦？\n&姜维\n孩儿都已经这年纪了，续弦只会破坏其他\n女子的幸福。\n&姜母\n嗯…只是做娘的都比较自私，还是希望\n这时候有人能照顾你呀。\n&姜维\n没关系，孩儿会自己照顾自己。"]},{"op":"delay","args":[5]},{"op":"actor_appear","args":[2,41,91,0,0]},{"op":"actor_appear","args":[24,46,91,0,0]},{"op":"actor_appear","args":[1,51,97,0,0]},{"op":"actor_move","args":[0,2,0,41,55,0]},{"op":"actor_move","args":[0,24,0,46,55,0]},{"op":"actor_move","args":[0,1,0,51,55,0]},{"op":"actor_action","args":[2,0]},{"op":"actor_action","args":[24,0]},{"op":"actor_action","args":[1,0]},{"op":"delay","args":[5]},{"op":"actor_face","args":[0,0,2]},{"op":"dialog","args":["&姜维\n咦？！你们怎么会…"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[920],[923]],"end":662},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,30,65535]},{"op":"actor_appear","args":[573,32,58,1,0]},{"op":"actor_appear","args":[562,38,72,3,0]},{"op":"actor_appear","args":[0,45,46,3,0]},{"op":"actor_appear","args":[563,42,69,3,0]},{"op":"actor_appear","args":[564,47,67,3,0]},{"op":"actor_appear","args":[566,39,64,3,0]},{"op":"actor_appear","args":[565,35,59,3,0]},{"op":"actor_appear","args":[569,44,60,3,0]},{"op":"actor_appear","args":[570,40,54,3,0]},{"op":"actor_appear","args":[574,44,53,3,0]},{"op":"actor_appear","args":[575,40,46,3,0]},{"op":"actor_appear","args":[576,40,40,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["传说的英雄"]},{"op":"place_name","args":["天水冀城"]},{"op":"dialog","args":["&旅人\n大家都知道，咱们冀城出了个了不起的\n英雄，那个人就是姜维大将军。\n&学者\n嗯…他真的是英雄吗？如果真要是的话，\n怎么会在最后平乱时死得那么突兀？\n&旅人\n这可是有重重内幕，知道这件事的，\n只有三个人，一个是现任大司马，一个\n是我，另一个不能说。\n&学者\n友滑兄，鬼扯也有个限度好吗？\n&旅人\n外地人愚蠢，难道我们这些家乡父老也要\n跟著蠢吗？\n&旅人\n我可以很大胆跟各位表示，姜维大将军\n是为了避免底下人拥护他当皇帝才诈死。\n&女子\n哦？诈死？\n&男子\n这个看法有点创意。\n&旅人\n别看我这样，当年我可跟过大将军南征\n北讨，他的英雄风范可是一直看在眼里。\n&旅人\n当时我是常败军的一员，曾经有一次和\n邓艾打仗的时候，被邓艾带兵追杀。\n&文官\n你太扯淡了吧，邓艾追杀你这小兵？\n&旅人\n话可不是这样说，邓艾这老贼残忍狡猾\n，连个小兵都不肯放过。\n&旅人\n言归正传，正当危急之时，大将军忽然\n从旁杀出，挥动手中长枪，一枪就撂倒\n一个人，最后和邓艾打起来。\n&旅人\n哪知邓艾那小人，居然叫弓弩手对大将军\n射击，结果你们知道怎么样吗？\n&武官\n大将军逃跑？\n&旅人\n错，大将军不慌不忙，勇敢地挥动手中\n长枪挡住那漫天飞箭，数万支箭居然都\n无法伤他分毫。\n&旅人\n而更感人的是，他居然为了保护那时候\n受伤的我而寸步不移。\n&姜维\n太夸张了，邓艾从来没带过那么多\n弓弩手吧。\n&旅人\n老伯安静点，人家贼人随时都能聚兵百万\n，几万弓弩手不过是小意思。\n&姜维\n抱歉，那最后大将军怎么样了？\n&旅人\n都是你在那边乱说话，让精彩的故事\n被打断了。\n&旅人\n正当危急之时，大将军终于使出绝招，\n忽然间他全身散发金色闪光，你们知道\n那是什么？那可是传说中的“圣光气”。\n&旅人\n邓艾见到大将军的实力，知道再有保留\n就老猫烧须了，当场运起“浑天宝鉴”\n心法。\n&姜维\n他到底在说什么呀…"]},{"op":"delay","args":[5]},{"op":"play_sound","args":[14]},{"op":"actor_appear","args":[2,45,5,2,0]},{"op":"actor_move","args":[0,2,0,45,40,2]},{"op":"actor_action","args":[2,0]},{"op":"actor_face","args":[0,0,0]},{"op":"dialog","args":["&姜维\n你来了呀？\n&杨兰\n真不敢相信，明明说约好在冀城碰面，\n你居然跑来这里听无聊的说书。\n&姜维\n抱歉，实在是有点好奇那个人会怎么说\n，哪知道变成神怪大战。\n&杨兰\n算了，毕竟你也算是守信，再埋怨你就\n显得太不近人情了。\n&杨兰\n走吧，在路上可要交代一下这段时间\n你在做什么。\n&姜维\n那相对地，你也说一下这段时间在\n做什么吧。\n&杨兰\n哦？一段时间不见，侵略性变强了？"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[921],[923]],"end":692},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,30,65535]},{"op":"actor_appear","args":[573,32,58,1,0]},{"op":"actor_appear","args":[562,38,72,3,0]},{"op":"actor_appear","args":[0,45,46,3,0]},{"op":"actor_appear","args":[563,42,69,3,0]},{"op":"actor_appear","args":[564,47,67,3,0]},{"op":"actor_appear","args":[566,39,64,3,0]},{"op":"actor_appear","args":[565,35,59,3,0]},{"op":"actor_appear","args":[569,44,60,3,0]},{"op":"actor_appear","args":[570,40,54,3,0]},{"op":"actor_appear","args":[574,44,53,3,0]},{"op":"actor_appear","args":[575,40,46,3,0]},{"op":"actor_appear","args":[576,40,40,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["传说的英雄"]},{"op":"place_name","args":["天水冀城"]},{"op":"dialog","args":["&旅人\n大家都知道，咱们冀城出了个了不起的\n英雄，那个人就是姜维大将军。\n&学者\n嗯…他真的是英雄吗？如果真要是的话，\n怎么会在最后平乱时死得那么突兀？\n&旅人\n这可是有重重内幕，知道这件事的，\n只有三个人，一个是现任大司马，一个\n是我，另一个不能说。\n&学者\n友滑兄，鬼扯也有个限度好吗？\n&旅人\n外地人愚蠢，难道我们这些家乡父老也要\n跟著蠢吗？\n&旅人\n我可以很大胆跟各位表示，姜维大将军\n是为了避免底下人拥护他当皇帝才诈死。\n&女子\n哦？诈死？\n&男子\n这个看法有点创意。\n&旅人\n别看我这样，当年我可跟过大将军南征\n北讨，他的英雄风范可是一直看在眼里。\n&旅人\n当时我是常败军的一员，曾经有一次和\n邓艾打仗的时候，被邓艾带兵追杀。\n&文官\n你太扯淡了吧，邓艾追杀你这小兵？\n&旅人\n话可不是这样说，邓艾这老贼残忍狡猾\n，连个小兵都不肯放过。\n&旅人\n言归正传，正当危急之时，大将军忽然\n从旁杀出，挥动手中长枪，一枪就撂倒\n一个人，最后和邓艾打起来。\n&旅人\n哪知邓艾那小人，居然叫弓弩手对大将军\n射击，结果你们知道怎么样吗？\n&武官\n大将军逃跑？\n&旅人\n错，大将军不慌不忙，勇敢地挥动手中\n长枪挡住那漫天飞箭，数万支箭居然都\n无法伤他分毫。\n&旅人\n而更感人的是，他居然为了保护那时候\n受伤的我而寸步不移。\n&姜维\n太夸张了，邓艾从来没带过那么多\n弓弩手吧。\n&旅人\n老伯安静点，人家贼人随时都能聚兵百万\n，几万弓弩手不过是小意思。\n&姜维\n抱歉，那最后大将军怎么样了？\n&旅人\n都是你在那边乱说话，让精彩的故事\n被打断了。\n&旅人\n正当危急之时，大将军终于使出绝招，\n忽然间他全身散发金色闪光，你们知道\n那是什么？那可是传说中的“圣光气”。\n&旅人\n邓艾见到大将军的实力，知道再有保留\n就老猫烧须了，当场运起“浑天宝鉴”\n心法。\n&姜维\n他到底在说什么呀…"]},{"op":"delay","args":[5]},{"op":"play_sound","args":[57]},{"op":"actor_appear","args":[1,45,5,2,0]},{"op":"actor_move","args":[0,1,0,45,40,2]},{"op":"actor_action","args":[1,0]},{"op":"actor_face","args":[0,0,0]},{"op":"dialog","args":["&负n﹑ㄓ"]},{"op":"actor_action","args":[1,6]},{"op":"dialog","args":["&诸葛果\n和主公相约，果不敢迟到。\n&诸葛果\n只是…主公真的要放任那个人胡说八道？\n如果允许的话，果可以…\n&姜维\n没关系，这样乱讲反而比较好，至少\n不会有人真的把它当真。\n&诸葛果\n主公害怕成为英雄的想法固然很好，但也\n请不要太执著。\n&诸葛果\n如果世人认为您是真正的英雄，那么不管\n怎么隐瞒，到最后还是会被重新评价。\n&姜维\n你太会夸奖人了。\n&诸葛果\n果只是实话实说而已。\n&姜维\n走吧，在路上你可以交代一下这一年\n到底做了些什么。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[922],[923]],"end":720},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,30,65535]},{"op":"actor_appear","args":[573,32,58,1,0]},{"op":"actor_appear","args":[562,38,72,3,0]},{"op":"actor_appear","args":[0,45,46,3,0]},{"op":"actor_appear","args":[563,42,69,3,0]},{"op":"actor_appear","args":[564,47,67,3,0]},{"op":"actor_appear","args":[566,39,64,3,0]},{"op":"actor_appear","args":[565,35,59,3,0]},{"op":"actor_appear","args":[569,44,60,3,0]},{"op":"actor_appear","args":[570,40,54,3,0]},{"op":"actor_appear","args":[574,44,53,3,0]},{"op":"actor_appear","args":[575,40,46,3,0]},{"op":"actor_appear","args":[576,40,40,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["传说的英雄"]},{"op":"place_name","args":["天水冀城"]},{"op":"dialog","args":["&旅人\n大家都知道，咱们冀城出了个了不起的\n英雄，那个人就是姜维大将军。\n&学者\n嗯…他真的是英雄吗？如果真要是的话，\n怎么会在最后平乱时死得那么突兀？\n&旅人\n这可是有重重内幕，知道这件事的，\n只有三个人，一个是现任大司马，一个\n是我，另一个不能说。\n&学者\n友滑兄，鬼扯也有个限度好吗？\n&旅人\n外地人愚蠢，难道我们这些家乡父老也要\n跟著蠢吗？\n&旅人\n我可以很大胆跟各位表示，姜维大将军\n是为了避免底下人拥护他当皇帝才诈死。\n&女子\n哦？诈死？\n&男子\n这个看法有点创意。\n&旅人\n别看我这样，当年我可跟过大将军南征\n北讨，他的英雄风范可是一直看在眼里。\n&旅人\n当时我是常败军的一员，曾经有一次和\n邓艾打仗的时候，被邓艾带兵追杀。\n&文官\n你太扯淡了吧，邓艾追杀你这小兵？\n&旅人\n话可不是这样说，邓艾这老贼残忍狡猾\n，连个小兵都不肯放过。\n&旅人\n言归正传，正当危急之时，大将军忽然\n从旁杀出，挥动手中长枪，一枪就撂倒\n一个人，最后和邓艾打起来。\n&旅人\n哪知邓艾那小人，居然叫弓弩手对大将军\n射击，结果你们知道怎么样吗？\n&武官\n大将军逃跑？\n&旅人\n错，大将军不慌不忙，勇敢地挥动手中\n长枪挡住那漫天飞箭，数万支箭居然都\n无法伤他分毫。\n&旅人\n而更感人的是，他居然为了保护那时候\n受伤的我而寸步不移。\n&姜维\n太夸张了，邓艾从来没带过那么多\n弓弩手吧。\n&旅人\n老伯安静点，人家贼人随时都能聚兵百万\n，几万弓弩手不过是小意思。\n&姜维\n抱歉，那最后大将军怎么样了？\n&旅人\n都是你在那边乱说话，让精彩的故事\n被打断了。\n&旅人\n正当危急之时，大将军终于使出绝招，\n忽然间他全身散发金色闪光，你们知道\n那是什么？那可是传说中的“圣光气”。\n&旅人\n邓艾见到大将军的实力，知道再有保留\n就老猫烧须了，当场运起“浑天宝鉴”\n心法。\n&姜维\n他到底在说什么呀…"]},{"op":"delay","args":[5]},{"op":"play_sound","args":[56]},{"op":"actor_appear","args":[24,45,5,2,0]},{"op":"actor_move","args":[0,24,0,45,40,2]},{"op":"actor_action","args":[24,0]},{"op":"actor_face","args":[0,0,0]},{"op":"dialog","args":["&姜维\n咦？\n&曹绫\n别小看曹家的情报能力，就算你躲到海外\n我都能把你抓出来。\n&姜维\n本来想要在这里隐姓埋名过一辈子，看来\n这梦想还真没那么容易实现。\n&曹绫\n你以为我是为了魏国来找你？不用担心，\n现在的魏国根本用不著你。\n&姜维\n虽然让人放心，但你说话还真不留情。\n&曹绫\n如果说，我是以曹绫这个女人的身份\n来找你，你会怎么反应？\n&姜维\n该怎么反应呢？说实话可考倒我了。\n&曹绫\n跟我来吧，在路上可以给你足够的时间\n来思考。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[923],[]],"end":744},{"op":"play_sound","args":[34]},{"op":"change_scene","args":[2,65535,65535,36,65535]},{"op":"actor_appear","args":[0,40,54,1,0]},{"op":"actor_appear","args":[2,45,49,3,0]},{"op":"actor_appear","args":[24,45,54,3,0]},{"op":"actor_appear","args":[1,45,59,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["三人的决定"]},{"op":"place_name","args":["冀城姜家"]},{"op":"dialog","args":["&姜维\n本来以为可以躲在这地方不被人发现，\n没想到还是被你们找到了。\n&杨兰\n好像还挺不甘愿…\n&曹绫\n别小看我们的情报能力，要找到你并不是\n什么难事。\n&姜维\n杨兰和诸葛果找我还能理解，为什么连\n公主都跑来？\n&曹绫\n你真的不清楚？\n&杨兰\n越来越让人生气了。\n&诸葛果\n主公在战后就忽然诈死消失，让身边\n许多人都无所适从。\n&诸葛果\n主公这样的作为虽然有所考量，但是却没\n考虑到被留下的人的心情。\n&姜维\n（诸葛果似乎真的生气了，她生气的样子\n真恐怖。比起来，邓艾或文鸯都只是\n小意思而已。）"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n真的很对不起，当时我脑袋只能想到这样\n的烂主意…实在是情况太急迫了。"]},{"op":"delay","args":[5]},{"op":"actor_action","args":[0,0]},{"op":"dialog","args":["&曹绫\n其实呢，我先要跟你说一件事…\n&曹绫\n这段时间我一直在思考自己的事，究竟\n我想要什么样的未来。\n&姜维\n这也难怪，过去这将近二十年的时间，\n你几乎都在为曹家的存续奋斗，根本\n没有时间思考自己的事。\n&曹绫\n想知道我在想什么事吗？\n&姜维\n可以告诉我吗？\n&曹绫\n母亲在我小的时候就遇害了，但在印象中\n，她个个性温厚，总是在迷迷糊糊过日子\n，是个没有人会讨厌她的好人。\n&曹绫\n但是呢，在之前和辛宪英见面时，她居然\n跟我说了母亲的另外一面。\n&曹绫\n她原来对自己的感情非常执著，她嫁给\n那害死她的父皇并不是被强迫的。\n&曹绫\n我可以体会李明当年不告诉我这件事情\n的原因，因为她比谁爱母亲，根本无法\n原谅做出那种事的父皇。\n&曹绫\n嗯…我要说的是…那个…其实…我虽然\n个性上有许多部份和母亲不太像，但\n或许在这一点上很像。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹绫\n我想了很久…也问了自己很久…或许我\n觉得将来能够在你身边是种不错的选择…\n&姜维\n咦？\n&杨兰\n真不知道你怎么会运气这么好，连这位\n魏国公主都看上你了。\n&诸葛果\n相信她一定能成为主公的好内助。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n等等，你们应该知道关于香的事情…\n&曹绫\n没有关系，都到了这个年纪，早就不计较\n什么名份。\n&杨兰\n尹香就当你永远的正妻，我们只要能够\n陪伴在你身边就够了。\n&诸葛果\n请别在意果，不管是当仆人或是奴隶，\n果都愿为主公服务。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n我该怎么说你们呢…\n&曹绫\n你认为自己有选择的权力？伯母那边早就\n已经欣然同意了，难道你这抛弃母亲多年\n的不孝子还想要再不孝一次？\n&姜维\n真是伤脑筋…"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[920],[923]],"end":768},{"op":"play_sound","args":[109]},{"op":"change_scene","args":[2,65535,65535,59,65535]},{"op":"actor_appear","args":[0,47,98,0,0]},{"op":"actor_appear","args":[2,53,98,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["久别的重逢"]},{"op":"place_name","args":["冀城附近"]},{"op":"actor_move","args":[0,0,0,47,57,1]},{"op":"actor_move","args":[0,2,0,53,57,3]},{"op":"actor_action","args":[0,0]},{"op":"actor_action","args":[2,0]},{"op":"dialog","args":["&杨兰\n原来如此，伯母在这一年已经过世了…\n&姜维\n不用太难过，毕竟已经算是享了天寿。\n能够在她人生最后一刻待在她身边，\n我也觉得没有遗憾了。\n&姜维\n你这一年过得应该很轰轰烈烈吧…仇池\n一战的名声可是响彻天下。\n&杨兰\n哈哈哈，想低调都不行。\n&杨兰\n我的想法很简单，与其一直忍耐，然后\n到最后爆发仇杀，倒不如现在就一直进行\n小规模战争。\n&杨兰\n透过这样的战争，也可以有效消化掉那些\n过剩的战力，避免制造问题。\n&姜维\n不错的想法，现在太平之世最大的障碍，\n就是那些因为没有战争而失去工作的\n士兵。\n&姜维\n虽说可以让士兵们回归农耕，但短时间\n内释放大量人力，只会造成耕地短缺。\n&杨兰\n总之事情就是这样，先别管我的事了。\n现在是要问你的决定。\n&杨兰\n既然当初跟我约好一年后在这里相见，\n应该就不会只是这样说几句话吧。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[0,0,3]},{"op":"dialog","args":["&姜维\n记得你当年对我说过的那些话吗？\n&杨兰\n当然记得。\n&姜维\n你说一直在等著我的回应，只是…\n&杨兰\n不需要了。"]},{"op":"actor_face","args":[0,0,1]},{"op":"dialog","args":["&姜维\n咦？\n&杨兰\n都已经到了这个年纪，还会在乎那外在\n的无聊形式？妻子的角色就永远留给\n尹香就好了。\n&杨兰\n只是你愿意将剩下的人生交给我吗？\n&姜维\n这怎么比较像是我该问你的话？\n&杨兰\n你当我会给你机会说吗？\n&姜维\n哈哈哈，这些年来我面对郭淮也好，\n陈泰也好，陆抗也好，甚至是司马昭或是\n邓艾，都没有一定会输给他们的感觉。\n&姜维\n只有面对你我觉得一点胜算也没有。\n&姜维\n如何？仇池国还有我的位子吗？\n&杨兰\n我还以为你会要我跟你回冀城…"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n现在留在冀城的只剩下回忆，如果一直\n停留在这里，相信娘和香也不愿意看见。\n&姜维\n虽说迟了点，但我还是希望能用剩余的\n人生来向前迈进。"]},{"op":"actor_action","args":[2,6]},{"op":"dialog","args":["&杨兰\n就等著你这句话，我们仇池国欢迎你。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[921],[923]],"end":792},{"op":"play_sound","args":[114]},{"op":"change_scene","args":[2,65535,65535,59,65535]},{"op":"actor_appear","args":[0,47,98,0,0]},{"op":"actor_appear","args":[1,53,98,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["久别的重逢"]},{"op":"place_name","args":["冀城附近"]},{"op":"actor_move","args":[0,0,0,47,57,1]},{"op":"actor_move","args":[0,1,0,53,57,3]},{"op":"actor_action","args":[0,0]},{"op":"actor_action","args":[1,0]},{"op":"dialog","args":["&诸葛果\n没想到主公的母亲居然在这一年过世了…\n&姜维\n不用太难过，毕竟已经算是享了天寿。\n能够在她人生最后一刻待在她身边，\n我也觉得没有遗憾了。\n&姜维\n你这一年应该都待在思远的府中吧，我猜\n他不管做什么事情都离不开你。\n&诸葛果\n主公果然睿智。小瞻虽然已经颇有才干，\n但目前还是缺乏信心。\n&诸葛果\n其实果目前也只是在引导他，让小瞻慢慢\n建立起自己的信心而已。\n&姜维\n思远是我看重能够领导下个世代的人。\n&姜维\n他年轻，有良好品德和崇高的声誉。\n比起我这样毁誉参半的人，他更是适合\n领导大汉。\n&诸葛果\n不对，主公是自愿背负起一切污名\n才会变成这样，您要是愿意，现在\n绝对还是大汉不可动摇的英雄。\n&姜维\n幼常以为自己能够背负所有污名，把我\n拱成英雄，消灭陛下势力就会天下太平。\n&姜维\n但是他错了，这样只会制造下一个董卓\n或曹操，这个回圈终究没有结束。\n&姜维\n我掌握的权力太大，名声也太高，根本\n就无人能够制衡我。\n&姜维\n相对来说，思远虽然有美名，但他的实力\n终究是不足…抱歉，一不小心就多说了。\n&诸葛果\n主公说得很对，今后不需要强人，也不\n需要英雄，今后应该是建立一个需要所有\n平凡人齐心才能维持下去的天下。\n&姜维\n嗯…听起来很梦幻，但我们确实在一步步\n让它实现。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n有件事情我想跟你说…\n&诸葛果\n不需要了。"]},{"op":"actor_face","args":[0,0,3]},{"op":"actor_face","args":[0,0,1]},{"op":"dialog","args":["&姜维\n咦？我明明还没开口…\n&诸葛果\n主公不会无端要果在一年之后前来冀城\n，想来想去也只有一种可能。\n&诸葛果\n果这些年陪在主公身边，要的绝对不是\n这个。\n&诸葛果\n而是这伴随的过程就已经让果觉得很\n快乐了。\n&诸葛果\n觉得很不可思议吗？但人其实就是一种\n需要感受到被他人需要的生物，果只是\n顺应的这种本能生活著而已。\n&姜维\n这种固执劲究竟像谁呢？\n&诸葛果\n这就是诸葛果这个女人的本性。\n&姜维\n那么…诸葛家还有我的位子吗？\n&诸葛果\n还以为主公会要果跟您回冀城…"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n现在留在冀城的只剩下回忆，如果一直\n停留在这里，相信娘和香也不愿意看见。\n&姜维\n虽说迟了点，但我还是希望能用剩余的\n人生来向前迈进。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&诸葛果\n果明白了，请主公跟随果前往吧。"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[922],[923]],"end":816},{"op":"play_sound","args":[113]},{"op":"change_scene","args":[2,65535,65535,59,65535]},{"op":"actor_appear","args":[0,47,98,0,0]},{"op":"actor_appear","args":[24,53,98,0,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["久别的重逢"]},{"op":"place_name","args":["冀城附近"]},{"op":"actor_move","args":[0,0,0,47,57,1]},{"op":"actor_move","args":[0,24,0,53,57,3]},{"op":"actor_action","args":[0,0]},{"op":"actor_action","args":[24,0]},{"op":"dialog","args":["&曹绫\n没想到伯母居然在这一年过世了…\n&姜维\n不用太难过，毕竟已经算是享了天寿。\n能够在她人生最后一刻待在她身边，\n我也觉得没有遗憾了。\n&姜维\n你这段日子在做什么？扶持曹芳？\n还是回去谯郡故里？\n&曹绫\n应该说我什么都没做，只是在整理一下\n思绪而已。\n&姜维\n这也难怪，过去这将近二十年的时间，\n你几乎都在为曹家的存续奋斗，根本\n没有时间思考自己的事。\n&曹绫\n想知道我在想什么事吗？\n&姜维\n可以告诉我吗？\n&曹绫\n母亲在我小的时候就遇害了，但在印象中\n，她个个性温厚，总是在迷迷糊糊过日子\n，是个没有人会讨厌她的好人。\n&曹绫\n但是呢，在之前和辛宪英见面时，她居然\n跟我说了母亲的另外一面。\n&曹绫\n她原来对自己的感情非常执著，她嫁给\n那害死她的父皇并不是被强迫的。\n&曹绫\n我可以体会李明当年不告诉我这件事情\n的原因，因为她比谁爱母亲，根本无法\n原谅做出那种事的父皇。\n&曹绫\n嗯…我要说的是…那个…其实…我虽然\n个性上有许多部份和母亲不太像，但\n或许在这一点上很像。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[24,0,1]},{"op":"dialog","args":["&曹绫\n我想了很久…也问了自己很久…或许我\n觉得将来能够在你身边是种不错的选择…\n&姜维\n你也应该知道香…\n&曹绫\n没有关系的，都已经到了这个年纪，还会\n再在意名份就太愚蠢了。尹香本来就应该\n是你永远的妻子。\n&姜维\n你在邺城那边还有地方容纳我？"]},{"op":"actor_face","args":[24,0,3]},{"op":"dialog","args":["&曹绫\n咦？还以为会要我跟你回冀城…"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n现在留在冀城的只剩下回忆，如果一直\n停留在这里，相信娘和香也不愿意看见。\n&姜维\n虽说迟了点，但我还是希望能用剩余的\n人生来向前迈进。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹绫\n原来如此，那么就跟著我走吧。或许我们\n还可以绕路前去朝阳陵看看。\n&姜维\n朝阳陵？好熟的名字。\n&曹绫\n之前你看过皇兄的高平陵，现在是该让你\n看看母后的朝阳陵，相信她会很乐意见到\n你的。\n&姜维\n（这种表情丰富，言谈流畅开朗的样子\n，或许才是曹绫真正的面貌吧。）\n&姜维\n（看来我的一念之间不但帮她卸下了复兴\n魏国的重担，也解放了她的内心。这样的\n结果是再好不过的。）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[920],[923]],"end":859},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,24,65535]},{"op":"actor_appear","args":[0,61,50,1,0]},{"op":"actor_appear","args":[2,61,55,1,0]},{"op":"actor_appear","args":[592,74,52,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["永远的两人"]},{"op":"place_name","args":["仇池外族营帐"]},{"op":"actor_action","args":[592,6]},{"op":"dialog","args":["&氐族兵1\n报告，刚才汉军已经被我们击退，现在\n危机解除了。\n&杨兰\n很好，就说只要听我们的，再多汉军来\n也是送死而已。\n&氐族兵1\n义母果然神勇无比，义父您的用兵更是\n让人敬佩。\n&氐族兵1\n只是…到现在还不知道您叫什么名字…\n&姜维\n那一点也不重要，你还是跟著杨兰姓好了\n，杨飞龙这名字真的挺响亮的。"]},{"op":"actor_action","args":[592,0]},{"op":"dialog","args":["&氐族兵1\n嘿嘿，说得也是。其实我最近还编了一首\n战歌，到时打仗时唱一定能提振士气。"]},{"op":"actor_action","args":[592,3]},{"op":"dialog","args":["&氐族兵1\n手牵手，心逗阵。\n把握好时机，亲像飞龙飞上天。"]},{"op":"actor_action","args":[592,0]},{"op":"dialog","args":["&杨兰\n你先下去吧，这歌听得我头好痛…\n&氐族兵1\n义母呀，我发现您只要在义父身边，用词\n就变得文雅许多。"]},{"op":"actor_action","args":[2,2]},{"op":"dialog","args":["&杨兰\n废话这么多干嘛，还不快去准备战斗。\n&氐族兵1\n…是…"]},{"op":"actor_move","args":[0,592,0,94,52,1]},{"op":"actor_select","args":[0,592,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"actor_face","args":[0,0,2]},{"op":"actor_face","args":[2,0,0]},{"op":"dialog","args":["&姜维\n这里朝气蓬勃，真是个好地方。\n&杨兰\n一年多前可不是这样，当时这些失去领袖\n的外族部众，背负著起兵造反的罪名，\n一路上遭遇汉人攻击。\n&杨兰\n不管有参加过战斗的还是没参加过战斗的\n，几乎都受到毁灭性的打击。\n&姜维\n我记得齐万年那家伙似乎就期望看见这种\n景象，他根本不把自己族人生命当回事。\n&杨兰\n那些人也真是倒楣，自己族里有堆疯子，\n还被外面那些野心家利用。\n&姜维\n幼常早就预见到会这样，但他还是选择\n去做，他的罪孽绝对不轻。\n&姜维\n所以我得感谢你，如果不是你拯救这些人\n，我和幼常的罪孽将深重到无以复加。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&杨兰\n还是老样子呀，提到别人的事情就热中得\n不得了。\n&杨兰\n对自己倒是毫不关心。\n&姜维\n毕竟我还是不习惯没人依赖我的生活，\n总觉得忽然失去重心一样。\n&杨兰\n可怜的被虐狂，难怪当年尹香要加给你\n这么多枷锁，要不然你恐怕活不到现在。\n&杨兰\n不管怎么说，你还是要学会放下。\n你不是说过吗？天下不需要英雄，而是\n要大家互相扶持走下去。\n&姜维\n哈哈哈，我又忘记自己说过的话，\n该不会真的是年纪大了？\n&杨兰\n别担心，要是真的老人失智，也会有个\n永远的十七岁陪著你。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n咦？"]},{"op":"actor_face","args":[0,0,3]},{"op":"actor_appear","args":[61,45,54,1,0]},{"op":"actor_appear","args":[5,45,59,1,0]},{"op":"actor_appear","args":[802,45,49,1,0]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&宁随\n………\n&尹香\n………\n&诸葛亮\n………"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&杨兰\n怎么了吗？"]},{"op":"wait_frame","args":[]},{"op":"actor_face","args":[0,0,2]},{"op":"dialog","args":["&姜维\n没什么…\n&姜维\n（谢谢…因为你们，我的一生过得精采\n无比。）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[921],[923]],"end":898},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,3,65535]},{"op":"actor_appear","args":[0,60,65,3,0]},{"op":"actor_appear","args":[1,60,72,3,0]},{"op":"actor_appear","args":[214,43,68,1,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["永远的两人"]},{"op":"place_name","args":["雒阳大司马府"]},{"op":"dialog","args":["&黄月英\n真没想到伯约你最后还是进了我们家。\n&诸葛果\n娘，主公并没有进我们家…\n&黄月英\n呵呵呵…没关系，娘知道自己女儿的\n想法。\n&黄月英\n伯约，请把这里当作是自己家，如果可以\n的话，也希望你把我当作是自己娘亲来\n看待。"]},{"op":"actor_action","args":[0,6]},{"op":"dialog","args":["&姜维\n多谢丞相夫人的好意。\n&黄月英\n这就不打扰你们，我还要去和瞻儿沟通\n一下，他已经气了足足三天，这孩子真是\n永远都长不大。"]},{"op":"actor_action","args":[0,0]},{"op":"actor_move","args":[0,214,0,43,59,0]},{"op":"delay","args":[0]},{"op":"actor_move","args":[0,214,0,30,59,3]},{"op":"actor_select","args":[0,214,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"actor_face","args":[0,0,2]},{"op":"actor_face","args":[1,0,0]},{"op":"dialog","args":["&姜维\n看见诸葛家能够这么壮盛，真的感到\n相当欣慰。\n&姜维\n本来我一直在想，把事情都托付给思远\n是不是正确的决定。\n&诸葛果\n主公不用担心，小瞻他只要建立起自信，\n很多事情都能慢慢上轨道。\n&诸葛果\n更何况他身边还有许多人帮忙，不会有\n问题的。\n&姜维\n这样就好，如果思远还需要帮忙的话，\n我也随时都可以…\n&诸葛果\n不行！\n&姜维\n咦？\n&诸葛果\n抱歉，但是主公忘记自己曾经说过的话？\n&诸葛果\n今后不需要强人，也不需要英雄，今后\n应该是建立一个需要所有平凡人齐心才能\n维持下去的天下。\n&姜维\n你说得对，要是我再参入，到时搞不好\n就脱不了身，也只会让思远的立场越来\n越尴尬而已。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n话说回来，我发现你的个性其实还\n挺强悍的，和我当初的印象感觉差很多。\n&诸葛果\n如果主公希望的话，果也可以改正…只是\n…这是果的本性，也请主公明白。\n&姜维\n不用担心，我就一直在想你是哪里像丞相\n，直到现在我才明白，那颗强韧的心就是\n遗传自丞相最好的证明。\n&姜维\n今后你就照著自己的想法来面对我吧，\n这样或许对你我都比较轻松。\n&诸葛果\n是的，主公。\n&姜维\n你果然还是很固执呀…"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n咦？"]},{"op":"actor_face","args":[0,0,0]},{"op":"actor_appear","args":[61,59,54,2,0]},{"op":"actor_appear","args":[5,54,54,2,0]},{"op":"actor_appear","args":[802,64,54,2,0]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&宁随\n………\n&尹香\n………\n&诸葛亮\n………"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&诸葛果\n怎么了吗？"]},{"op":"wait_frame","args":[]},{"op":"actor_face","args":[0,0,2]},{"op":"dialog","args":["&姜维\n没什么…\n&姜维\n（谢谢…因为你们，我的一生过得精采\n无比。）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[922],[923]],"end":932},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,61,65535]},{"op":"actor_appear","args":[0,63,69,1,0]},{"op":"actor_appear","args":[24,63,63,1,0]},{"op":"actor_appear","args":[68,72,66,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["永远的两人"]},{"op":"place_name","args":["邺城东乡公主宅邸"]},{"op":"dialog","args":["&曹芳\n姑母，您什么时候回到邺城？怎么也不让\n侄儿迎接您。\n&曹绫\n毕竟我们也不是什么重要人物，实在不需\n要麻烦你。\n&曹芳\n可是…就算扣除掉姑母，姜伯约大将军\n也是我们魏国的恩人，怎么可以怠慢？\n&姜维\n魏王别这样说，魏国能够再兴靠的是各位\n魏臣和曹氏家族成员的齐心合作，和姜维\n一点关系也没有。\n&曹绫\n今后侄儿你也尽量不要往这里跑，否则\n要是这里成为魏国的影子政府就糟了。\n&曹芳\n可是侄儿今后还有很多问题…\n&曹绫\n那你应该去找陈泰、鲁芝或是夏侯霸，\n一国的统治者应该有这样的判断能力。\n&曹绫\n不用担心，目前你做得很好，皇兄把大魏\n托付你绝对没有错。\n&曹绫\n多相信自己一点，魏国会越来越好的。\n&曹芳\n那么侄儿告退了，多谢姑母您的一番话。"]},{"op":"actor_move","args":[0,68,0,91,66,1]},{"op":"actor_select","args":[0,68,0,0,0,0,6]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"actor_face","args":[0,0,0]},{"op":"actor_face","args":[24,0,2]},{"op":"dialog","args":["&曹绫\n这样就行了，总不能让侄儿他一直\n依赖我。\n&姜维\n这样的选择很正确，现在依靠一个人撑起\n一个国家或天下的时代已经过去，接下来\n应该是群策群力的新时代。\n&曹绫\n话说得很大，真的有办法实现吗？\n&姜维\n为了达成这个目标，我们已经付出太重大\n的牺牲，非得实现不可。\n&曹绫\n嗯…这个话题就到此为止吧。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹绫\n我花了很多时间才弄清楚自己的想法，\n想要跟你度过余生。\n&曹绫\n说实话我觉得自己很幸运，我们曹家女子\n能够凭著自己意志来决定归属的，恐怕\n我是第一个。\n&曹绫\n不管是清河长公主、金阳公主或是献穆\n皇后，大家都是被迫和自己不认识的人\n成婚。\n&姜维\n结果你以自己的意志决定是我？\n&曹绫\n觉得很不可思议吗？因为我们见面的次数\n寥寥可数，远不如你身边的两个女人？\n&曹绫\n不，这一点也不重要。\n&曹绫\n只要当我问起自己，最希望陪在身边的\n是谁，而最后浮现的人就是你时，这样\n就够了。\n&姜维\n说得也是，时间的长短并不是最重要的，\n而是内心的感觉。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n咦？"]},{"op":"actor_face","args":[0,0,3]},{"op":"actor_appear","args":[61,54,65,1,0]},{"op":"actor_appear","args":[5,54,59,1,0]},{"op":"actor_appear","args":[802,54,71,1,0]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&宁随\n………\n&尹香\n………\n&诸葛亮\n………"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹绫\n怎么了吗？"]},{"op":"wait_frame","args":[]},{"op":"actor_face","args":[0,0,0]},{"op":"dialog","args":["&姜维\n没什么…\n&姜维\n（放心过这样的生活就好，是吗？）"]},{"op":"dialog","args":["&姜维\n（谢谢…因为你们，我的一生过得精采\n无比。）"]},{"op":"endif","args":[]},{"op":"if","cond":"test_flags","args":[[923],[]],"end":968},{"op":"play_sound","args":[16]},{"op":"change_scene","args":[2,65535,65535,33,65535]},{"op":"actor_appear","args":[0,34,56,3,0]},{"op":"actor_appear","args":[24,39,56,3,0]},{"op":"actor_appear","args":[2,39,52,3,0]},{"op":"actor_appear","args":[1,39,61,3,0]},{"op":"fade_out","args":[]},{"op":"title_text","args":["永远的羁绊"]},{"op":"place_name","args":["尹香墓前"]},{"op":"dialog","args":["&姜维\n香，请你谅解。就算不是奉母亲之命，\n我内心也倾向有人能够扶持我走完剩下\n的人生。\n&姜维\n不过你是我妻子这件事情是永远不会\n改变的。感谢你在我人生最低潮时帮助\n我走过来。"]},{"op":"delay","args":[5]},{"op":"actor_face","args":[0,0,1]},{"op":"dialog","args":["&杨兰\n结束了？\n&姜维\n嗯，这样就好。要是一直沉浸在过去，\n恐怕将永远无法向未来迈进。"]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹绫\n接下来有件很重要的事。\n&杨兰\n我们三人虽然决定同时陪伴你，但还是\n要分个次序高低。\n&诸葛果\n请主公不要在意果，只要专心搞定两位\n就行。\n&曹绫\n论年纪，我略长于杨兰。论家世，我们\n曹家也是高门第的家族。\n&曹绫\n所以我排在前面是理所当然的事。"]},{"op":"actor_face","args":[2,0,2]},{"op":"dialog","args":["&杨兰\n有道理，若比皱纹数的话还真是输你。"]},{"op":"actor_face","args":[24,0,0]},{"op":"dialog","args":["&曹绫\n哎呀，刚才那句话可不能当作没听到了。\n&曹绫\n我们出身名门的人很清楚该怎么保养，\n不像某些只会在骑马跑来跑去的，皮肤\n都弄坏掉了。"]},{"op":"actor_action","args":[2,2]},{"op":"dialog","args":["&杨兰\n哼，真要说的话，我可是一直待在姜维\n身边，诸葛果也勉强说过去。\n&杨兰\n而你呢？只是像个小偷一样，最后面才\n跑出来要分一杯羹，照先来先赢的道理，\n你应该是最小的。\n&曹绫\n哦？那么我们问问看姜维怎么决定。"]},{"op":"actor_face","args":[24,0,3]},{"op":"actor_face","args":[2,0,3]},{"op":"delay","args":[5]},{"op":"dialog","args":["&姜维\n咦？"]},{"op":"actor_appear","args":[61,53,55,3,0]},{"op":"actor_appear","args":[5,53,60,3,0]},{"op":"actor_appear","args":[802,53,50,3,0]},{"op":"wait_frame","args":[]},{"op":"delay","args":[5]},{"op":"dialog","args":["&曹绫\n怎么了吗？\n&杨兰\n你在发什么呆？\n&诸葛果\n主公似乎是看见了什么。"]},{"op":"wait_frame","args":[]},{"op":"dialog","args":["&姜维\n没什么…\n&姜维\n（谢谢…因为你们，我的一生过得精采\n无比。）"]},{"op":"fade_in","args":[]},{"op":"endif","args":[]},{"op":"endif","args":[]}]},"battles":[]});
})();
